import React, { useState } from 'react'
import { Row, Col, Form, Input, Button, Spin, Table, Icon, Tooltip } from 'antd'
import { get } from 'lodash'

const ValidationData = ({ onHandleSearchValidationData, initalFormData, form, validationDataInput, onHandleSearchValidationBtn, validationList, displayValidation, packageCode }) => {
  const [inputDisable, setInputDisable] = useState(true)
  const { setFieldsValue, getFieldDecorator } = form

  const hanndlePackageCode = (data) => {
    setFieldsValue({
      validation_unique_identifier: data
    })
  }

  const validationDataColumns = [
    {
      key: 'product_code',
      title: 'Product Code',
      dataIndex: 'product_code'
    },
    {
      key: 'code',
      title: 'Code',
      dataIndex: 'code'
    },
    {
      key: 'provider_code',
      title: 'Provider Code',
      dataIndex: 'provider_code'
    },
    {
      key: 'validation_unique_identifier',
      title: 'Unique Identifier',
      dataIndex: 'validation_unique_identifier'
    },
    {
      key: 'action',
      title: 'Copy',
      render: (data) =>
        <Tooltip placement='rightTop' title='Click to Fill Unique Identifier Below'>
          <Icon type='copy' className='pointer' onClick={() => hanndlePackageCode(data?.validation_unique_identifier)} />
        </Tooltip>
    }
  ]

  return (
    <Col span={24}>
      <Row type='flex'>
        <Col span={24}>
          <p className='custom-provider-heading'><b>Validation Data</b></p>

        </Col>
      </Row>

      <Row type='flex' justify='space-around'>
        <Col>
          <Input
            onChange={onHandleSearchValidationData}
            value={validationDataInput}
            placeholder='Input Code Here'
          />
        </Col>
        <Col>
          <Button
            type='primary'
            onClick={onHandleSearchValidationBtn}
            disabled={validationDataInput?.length === 0}
          >Search
          </Button>
        </Col>
      </Row>

      <br />

      <Row type='flex' justify='center' align='center'>
        <Col span={18}>
          <Spin spinning={false}>
            <Table
              bordered
              rowKey={(record) => record.code}
              columns={validationDataColumns}
              dataSource={validationList}
            />
          </Spin>
        </Col>
      </Row>

      <Row type='flex' justify='center'>
        <Col>
          <div className='input-wrapper'>
            <Form.Item label='Validation Unique Indentifier'>
              {
                getFieldDecorator('validation_unique_identifier', {
                  rules: [
                    {
                      required: displayValidation,
                      message: 'required'
                    }
                  ],
                  initialValue: get(initalFormData, 'validation_unique_identifier', packageCode)
                })(<Input className='small-size' placeholder='Validation Unique Identifier' disabled={inputDisable} />)
              }
            </Form.Item>
            <div className='icon-wrapper'>
              <Icon type='eye' className='icon-disable' onClick={() => setInputDisable(!inputDisable)} />
            </div>
          </div>
        </Col>
      </Row>
    </Col>
  )
}

export default ValidationData
