import React, { Component, Suspense } from 'react'
import { Row, Col, Form, Radio, Spin } from 'antd'
import { getFormItems } from '../../../../../../components/formItem'
import { get, size } from 'lodash'
import { reconTime } from '../../../PackageSection/commanFunctions'
const ReconStyleWrapper = React.lazy(() => import('./index.style'))
class ReconTime extends Component {
  state = {
    initialFormData: {},
    step2Data: []
  }

  componentDidMount () {
    const { initialData, step2Data } = this.props
    if (step2Data.length > 0) {
      this.setState({
        step2Data
      })
    }
    const { initialFormData } = this.state
    const data = initialData || {}
    if (size(data) > 0 && size(initialFormData) === 0) {
      const localData = reconTime(data)
      this.setState({
        initialFormData: localData
      })
    }
  }

  // onSubmitHandler=(e) => {
  //   e.preventDefault()
  //   const { form } = this.props
  //   this.props.form.validateFields((err, values) => {
  //     if (!err) {
  //       const formBody = form.getFieldsValue()
  //       // TODO:  remove the type for premium
  //       window.sessionStorage.setItem('reconTime', JSON.stringify(formBody))
  //       this.props.changePanel(5)
  //     }
  //   })
  // }
  render () {
    const { getFieldDecorator } = this.props.form
    const { initialFormData, step2Data } = this.state
    const attributesData = step2Data.length > 0 ? step2Data : (JSON.parse(window.sessionStorage.getItem('Step2')) || [])
    return (
      <Suspense fallback={<Spin tip='ReconTime Loading ...' />}>
        <ReconStyleWrapper>
          <Row type='flex' justify='center'>
            <Col className='lastField'>
              <Row type='flex' justify='center' gutter={20}>
                <Col span={18}>
                  <p className='heading-style'><b>What will be the recon time ?</b></p>
                </Col>
                <Col>
                  <Row type='flex'>
                    <Col span={18}>
                      <Form.Item>
                        {
                          getFieldDecorator('is_recon_time_derivable', {
                            rules: [
                              {
                                required: true,
                                message: 'Recon Time Required'
                              }
                            ],
                            initialValue: get(initialFormData, 'is_recon_time_derivable', '')
                          })(
                            <Radio.Group>
                              <Radio value='1'> same as request created at</Radio>
                              <Radio value='2'> add recon time in policy creation field as mandatory</Radio>
                              <Radio value='3'>
                                <span className='radio-class'>
                                  <Row type='flex' className='inline-data attribute-condition'>
                                    <Col className='flex-center-wrapper'>
                                      <p className='text-between floatLeft'>same as policy data</p>
                                    </Col>
                                    <Col>
                                      {
                                        getFormItems.call(this, {
                                          formName: 'recon_time_derived_from_product_attribute_id',
                                          type: 'nested-tree-select',
                                          required: this.props.fieldCheckCondition('is_recon_time_derivable', '3'),
                                          options: attributesData,
                                          optionKey: 'id',
                                          optionDisplayName: 'name',
                                          className: 'small-size',
                                          initialValue: get(initialFormData, 'recon_time_derived_from_product_attribute_id', null)
                                        })
                                      }
                                    </Col>
                                  </Row>
                                </span>
                              </Radio>
                            </Radio.Group>
                          )
                        }
                      </Form.Item>
                    </Col>
                  </Row>
                </Col>
              </Row>
            </Col>
          </Row>
        </ReconStyleWrapper>
      </Suspense>
    )
  }
}
export default ReconTime
