export const localStorageUpdate = (data, formData) => {
  const newLocalStorage = {
    ...data,
    ...formData
  }
  window.sessionStorage.setItem('formData', JSON.stringify(newLocalStorage))
}
export const setFormFieldsDataFunction = (objectData, self) => {
  const { form } = self.props
  if (hasIn(objectData, 'coverage_start_same_as_policy_creation')) {
    if (objectData.coverage_start_same_as_policy_creation === 'true') {
      form.setFieldsValue({
        coverage_start_derived_from_product_attribute_id: null,
        coverage_start_buffer_days: 0
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'end_date_time_type')) {
    if (objectData.end_date_time_type === 1) {
      form.setFieldsValue({
        coverage_end_derived_from_product_attribute_id: null,
        coverage_end_diff_months_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'end_date_time_type')) {
    if (objectData.end_date_time_type === 2) {
      form.setFieldsValue({
        coverage_end_derived_from_product_attribute_id: null,
        coverage_end_diff_days_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'end_date_time_type')) {
    if (objectData.end_date_time_type === 3) {
      form.setFieldsValue({
        coverage_end_diff_months_from_coverage_start: null,
        coverage_end_diff_days_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }

  if (hasIn(objectData, 'endorsement_coverage_start_same_as_policy_creation')) {
    if (objectData.endorsement_coverage_start_same_as_policy_creation === 'true') {
      form.setFieldsValue({
        endorsement_coverage_start_derived_from_product_attribute_id: null,
        endorsement_coverage_start_buffer_days: 0
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'endorsement_end_date_time_type')) {
    if (objectData.endorsement_end_date_time_type === 1) {
      form.setFieldsValue({
        endorsement_coverage_end_derived_from_product_attribute_id: null,
        endorsement_coverage_end_diff_months_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'endorsement_end_date_time_type')) {
    if (objectData.endorsement_end_date_time_type === 2) {
      form.setFieldsValue({
        endorsement_coverage_end_derived_from_product_attribute_id: null,
        endorsement_coverage_end_diff_days_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'endorsement_end_date_time_type')) {
    if (objectData.endorsement_end_date_time_type === 3) {
      form.setFieldsValue({
        endorsement_coverage_end_diff_months_from_coverage_start: null,
        endorsement_coverage_end_diff_days_from_coverage_start: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }

  if (hasIn(objectData, 'is_recon_time_derivable')) {
    if (objectData.is_recon_time_derivable === '1') {
      form.setFieldsValue({
        recon_time_derived_from_product_attribute_id: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'document_generation_source')) {
    if (objectData.document_generation_source === 'not_required') {
      form.setFieldsValue({
        policy_creation_certificate_job: null,
        policy_creation_certificate_html: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'has_endorsement_flow')) {
    if (objectData.document_generation_source === 'false') {
      form.setFieldsValue({
        endorsement_timeout: null,
        endorsement_limit: null,
        endorsement_document_generation_source: 'not_required',
        policy_endorsement_certificate_job: null,
        policy_endorsement_certificate_html: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'policy_number_source')) {
    if (objectData.policy_number_source !== 'payload') {
      form.setFieldsValue({
        policy_number_derived_from_product_attribute_id: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'endorsement_document_generation_source')) {
    if (objectData.endorsement_document_generation_source === 'not_required') {
      form.setFieldsValue({
        policy_endorsement_certificate_job: null,
        policy_endorsement_certificate_html: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'has_blacklist_config')) {
    if (objectData.has_blacklist_config === 'false') {
      form.setFieldsValue({
        blacklist_config: null,
        blacklist_config_source_name: null
      })
      const data = { ...form.getFieldsValue() }
      localStorageUpdate(objectData, data)
    }
  }
  if (hasIn(objectData, 'use_formula')) {
    form.setFieldsValue({
      use_formula: objectData.use_formula === 1 ? 1 : 0,
    })
    const data = { ...form.getFieldsValue() }
    localStorageUpdate(objectData, data)
  }
  if (hasIn(objectData, 'country_id')) {
    const countryData = JSON.parse(window.sessionStorage.getItem('countriesData')) || []
    const countryName = countryData.find((item) => item.id === objectData.country_id)?.code
    form.setFieldsValue({
      country_code: countryName
    })
    const data = { ...form.getFieldsValue() }
    objectData.country_code = countryName
    localStorageUpdate(objectData, data)
  }
  const formData = { ...form.getFieldsValue() }
  return {
    ...objectData,
    ...formData
  }
}

export const payloadFormationFunction = (localStorageData = {}, step1Data) => {
  const premiumLogic = JSON.parse(window.sessionStorage.getItem('new_premium_logic')) || {}
  const premiumType = JSON.parse(window.sessionStorage.getItem('new_premium_type')) || ''
  const endorsementPremiumLogic = JSON.parse(window.sessionStorage.getItem('endorsement_new_premium_logic')) || {}
  const endorsementPremiumType = JSON.parse(window.sessionStorage.getItem('endorsement_premium_type')) || ''
  let configs = JSON.parse(window.sessionStorage.getItem('configList')) || []
  configs = configs.length > 0
    ? configs.map(item => {
        return {
          hash_id: Number(item.hashId), product_attribute_id: Number(item.attributeId)
        }
      })
    : []
  const blacklistConfigData = {
    source_name: get(localStorageData, 'blacklist_config_source_name', ''),
    configs: configs
  }
  // const reminderConfigsData = [{
  //   interval: get(localStorageData, 'reminder_interval', ''),
  //   interval_unit: get(localStorageData, 'reminder_interval_unit', ''),
  //   reminder_type: get(localStorageData, 'reminder_reminder_type', '')
  // }]

  const isCombined = premiumType.includes('_')
  // const isEndorsementCombined = endorsementPremiumType.includes('_')
  const newPremiumLogicType = isCombined ? premiumType.split('_')[0] : premiumType
  // const newEndorsementPremiumLogicType = isEndorsementCombined ? endorsementPremiumType.split('_')[0] : endorsementPremiumType

  let data = {
    ...payload,
    ...localStorageData,
    product_id: get(step1Data, 'id', ''),
    use_formula: localStorageData?.use_formula,
    formula_expression: localStorageData?.formula,
    coverage_start_buffer_days: localStorageData.coverage_start_buffer_days ? Number(localStorageData.coverage_start_buffer_days) : 0,
    coverage_end_diff_days_from_coverage_start: localStorageData.coverage_end_diff_days_from_coverage_start ? Number(localStorageData.coverage_end_diff_days_from_coverage_start) : null,
    coverage_end_diff_months_from_coverage_start: localStorageData.coverage_end_diff_months_from_coverage_start ? Number(localStorageData.coverage_end_diff_months_from_coverage_start) : null,
    coverage_start_same_as_policy_creation: localStorageData.coverage_start_same_as_policy_creation === 'true',
    endorsement_coverage_start_buffer_days: localStorageData.endorsement_coverage_start_buffer_days ? Number(localStorageData.endorsement_coverage_start_buffer_days) : 0,
    endorsement_coverage_end_diff_days_from_coverage_start: localStorageData.endorsement_coverage_end_diff_days_from_coverage_start ? Number(localStorageData.endorsement_coverage_end_diff_days_from_coverage_start) : null,
    endorsement_coverage_end_diff_months_from_coverage_start: localStorageData.endorsement_coverage_end_diff_months_from_coverage_start ? Number(localStorageData.endorsement_coverage_end_diff_months_from_coverage_start) : null,
    endorsement_coverage_start_same_as_policy_endorsement: localStorageData.endorsement_coverage_start_same_as_policy_endorsement === 'true',
    is_recon_time_derivable: localStorageData.is_recon_time_derivable === '3',
    recon_time_derived_from_product_attribute_id: localStorageData.is_recon_time_derivable === '3' ? localStorageData.recon_time_derived_from_product_attribute_id : null,
    recon_time_required_from_policy_creation_request: localStorageData.is_recon_time_derivable === '2',
    policy_creation_certificate_job: localStorageData.document_generation_source === 'pasarpolis' ? `${get(step1Data, 'code', '')}-${localStorageData.code}-policy-creation` : null,
    policy_endorsement_certificate_job: localStorageData.endorsement_document_generation_source === 'pasarpolis' ? `${get(step1Data, 'code', '')}-${localStorageData.code}-policy-endorsement` : null,
    blacklist_config: blacklistConfigData,
    // reminder_configs: localStorageData.is_reminder_enabled ? reminderConfigsData : null,
    premium_logic: premiumLogic,
    premium_type: premiumType,
    endorsement_premium_logic: endorsementPremiumLogic,
    endorsement_premium_type: endorsementPremiumType
  }

  data = {
    ...data,
    new_premium_logic: {
      ...premiumLogic,
      premium_type: newPremiumLogicType
    }
  }

  if (Object.keys(endorsementPremiumLogic).length > 0) {
    data.endorsement_new_premium_logic = {
      ...endorsementPremiumLogic,
      premium_type: endorsementPremiumType
    }
  }

  // if (isCombined) {
  //   data = {
  //     ...data,
  //     premium_logic: premiumLogic.premium_logic
  //   }
  // } else {
  //   data = {
  //     ...data,
  //     new_premium_logic: {
  //       ...premiumLogic,
  //       premium_type: newPremiumLogicType
  //     }
  //   }
  // }

  delete data.end_date_time_type
  // window.sessionStorage.removeItem('new_premium_logic')
  // window.sessionStorage.removeItem('new_premium_type')
  // window.sessionStorage.removeItem('endorsement_new_premium_logic')
  // window.sessionStorage.removeItem('endorsement_premium_type')
  return data
}

export const packagePayloadFormation = (data = {}) => {
  const apiResponse = data
  const mapperObject = {
    ...apiResponse,
    formula: apiResponse.formula_expression,
    use_formula: apiResponse.use_formula,
    end_date_time_type: coverageEndDateOptionCheck(apiResponse),
    coverage_end_diff_days_from_coverage_start: apiResponse.coverage_end_diff_days_from_coverage_start,
    coverage_end_diff_months_from_coverage_start: apiResponse.coverage_end_diff_months_from_coverage_start,
    coverage_start_buffer_days: apiResponse.coverage_start_buffer_days,
    coverage_start_same_as_policy_creation: apiResponse.coverage_start_same_as_policy_creation,
    endorsement_end_date_time_type: coverageEndDateOptionCheck(apiResponse, 'endorsement'),
    endorsement_coverage_end_diff_days_from_coverage_start: apiResponse.endorsement_coverage_end_diff_days_from_coverage_start,
    endorsement_coverage_end_diff_months_from_coverage_start: apiResponse.endorsement_coverage_end_diff_months_from_coverage_start,
    endorsement_coverage_start_buffer_days: apiResponse.endorsement_coverage_start_buffer_days,
    endorsement_coverage_start_same_as_policy_creation: apiResponse.endorsement_coverage_start_same_as_policy_creation,
    is_recon_time_derivable: reconOptionCheck(apiResponse)
  }
  window.sessionStorage.setItem('formData', JSON.stringify(mapperObject))
  return mapperObject
}

const reconOptionCheck = (item) => {
  const { recon_time_derived_from_product_attribute_id: reconAttributeId, recon_time_required_from_policy_creation_request: reconTimeRequiredPolicyCreationRequest } = item
  if (reconTimeRequiredPolicyCreationRequest) {
    return '2'
  } else {
    return reconAttributeId ? '3' : '1'
  }
}

export const coverageEndDateOptionCheck = (apiResponse = {}, type = '') => {
  const date = type ? `${type}_coverage_end_diff_days_from_coverage_start` : 'coverage_end_diff_days_from_coverage_start'
  const month = type ? `${type}_coverage_end_diff_months_from_coverage_start` : 'coverage_end_diff_months_from_coverage_start'
  const attributeData = type ? `${type}_coverage_end_derived_from_product_attribute_id` : 'coverage_end_derived_from_product_attribute_id'
  if (get(apiResponse, date) === 0 && get(apiResponse, month) === 0 && get(apiResponse, attributeData) === null) {
    return 1
  } else {
    if (size(apiResponse) > 0) {
      if (get(apiResponse, date) !== null) {
        return 1
      } else if (get(apiResponse, month) !== null) {
        return 2
      } else if (get(apiResponse, attributeData) !== null) {
        return 3
      } else {
        return null
      }
    }
  }
}

