export const initialValidationData = (Step2Data, validation, name) => {
  const data = Step2Data.map(item => {
    const requiredData = validation.find(item => item.code === 'required') || {}
    if (item.code === 'package_id') {
      const oneOfData = validation.find(item => item.code === 'oneof') || {}
      return {
        product_attribute_code: item.code,
        product_attribute_id: item.id,
        validations: [
          {
            id: requiredData.id,
            value: null,
            code: requiredData.code
          },
          {
            id: oneOfData.id,
            value: name,
            code: oneOfData.code
          }
        ]
      }
    } else if (item.code === 'reference_id') {
      return {
        product_attribute_code: item.code,
        product_attribute_id: item.id,
        validations: [
          {
            id: requiredData.id,
            value: null,
            code: requiredData.code
          }
        ]
      }
    } else {
      return {
        product_attribute_code: item.code,
        product_attribute_id: item.id,
        validations: []
      }
    }
  })
  return data
}
