import React, { createContext, useReducer } from 'react'
import { get, setWith } from 'lodash'
import { localStorageSave } from './premiumLocalStorageSave'
// import { DEFAULT_MAPPED_DATA, DEFAULT_RANGED_DATA, DEFAULT_AGE_ROW_DATA } from './constants'

const state = {
  new_premium_logic: {},
  combined_type: '',
  type: '',
  fixed: '',
  derived: {},
  mapped: {},
  ranged: {},
  age: {},
  mapped_derived: {
    derived_attribute_id: null,
    mapped_attribute_id: null,
    data: [{
      _id: 1,
      showAddButton: true,
      showDeleteButton: false,
      value: {
        value: ''
      },
      operand: null
    }]
  },
  age_derived: {
    derived_attribute_id: null,
    first_parameter: {
      is_current_time: false,
      product_attribute_id: ''
    },
    second_parameter: {
      is_current_time: false,
      product_attribute_id: ''
    },
    unit: '',
    values: [{
      _id: 1,
      showAddButton: true,
      showDeleteButton: false,
      lower_operator: '',
      lower_operand: '',
      upper_operator: '',
      upper_operand: '',
      value: {
        value: ''
      }
    }
    ]
  },
  age_mapped: {
    mapped_attribute_id: null,
    first_parameter: {
      is_current_time: false,
      product_attribute_id: ''
    },
    second_parameter: {
      is_current_time: false,
      product_attribute_id: ''
    },
    unit: '',
    data: [
      {
        parent_id: 1,
        showAddButton: true,
        showDeleteButton: false,
        lower_operator: '',
        lower_operand: '',
        upper_operator: '',
        upper_operand: '',
        value: [{
          child_id: 1,
          showAddButton: true,
          showDeleteButton: false,
          operand: '',
          value: ''
        }]
      }
    ]
  },
  ranged_mapped: {
    ranged_attribute_id: null,
    mapped_attribute_id: null,
    data: [{
      parent_id: 1,
      showAddButton: true,
      showDeleteButton: false,
      lower_operator: '',
      lower_operand: '',
      upper_operator: '',
      upper_operand: '',
      value: [{
        child_id: 1,
        showAddButton: true,
        showDeleteButton: false,
        operand: '',
        value: ''
      }]
    }]
  }
}

const premiumInitialState = state => Object.keys(state).reduce((updatedValue, key) => {
  updatedValue = {
    ...updatedValue,
    [`endorsement_${key}`]: state[key]
  }
  return updatedValue
}, { ...state })
const initialState = { ...premiumInitialState(state) }
const store = createContext(initialState)
const { Provider } = store

const PremiumStateProvider = ({ children }) => {
  const [state, dispatch] = useReducer((state, action) => {
    switch (action.type) {
      case 'reset-all': {
        const result = { ...state }
        if (get(action, 'payload.view') === 'endorsement') {
          window.sessionStorage.removeItem('endorsement_new_premium_logic')
          // result.endorsement_new_premium_logic = undefined
          result.endorsement_new_premium_logic = undefined
          // Object.keys(initialState).forEach(item => {
          //   if (item.includes('endorsement')) {
          //     result = {
          //       ...result,
          //       [item]: initialState[item]
          //     }
          //   }
          // })
        } else {
          window.sessionStorage.removeItem('new_premium_logic')
          result.new_premium_logic = undefined
          // Object.keys(initialState).forEach(item => {
          //   if (!item.includes('endorsement')) {
          //     result = {
          //       ...result,
          //       [item]: initialState[item]
          //     }
          //   }
          // })
        }
        return result
      }
      case 'update-type': {
        let data = {}
        const view = get(action, 'payload.view')
        const type = view === 'endorsement' ? 'endorsement_type' : 'type'
        const combinedType = view === 'endorsement' ? 'endorsement_combined_type' : 'combined_type'

        data = {
          ...state,
          [type]: action.payload.state,
          [combinedType]: action.payload.state === 'combined' ? action.payload.value : '' // contains e.g. mapped_fixed, mapped_derived
        }

        if (action.payload.state === 'combined') {
          data = setWith(data, 'new_premium_logic.premium_type', action.payload.value.split('_')[0])
        } else {
          data = setWith(data, 'new_premium_logic.premium_type', action.payload.state)
        }

        if (get(data, type) !== 'combined') {
          window.sessionStorage.setItem(`${view === 'endorsement' ? 'endorsement_premium_type' : 'new_premium_type'}`, JSON.stringify(get(data, type, '')))
        } else {
          window.sessionStorage.setItem(`${view === 'endorsement' ? 'endorsement_premium_type' : 'new_premium_type'}`, JSON.stringify(get(data, combinedType, '')))
        }

        return data
      }
      case 'init-state': {
        let data = {}
        const view = get(action, 'payload.view')
        const type = view === 'endorsement' ? 'endorsement_type' : 'type'
        const combinedType = view === 'endorsement' ? 'endorsement_combined_type' : 'combined_type'

        data = {
          ...state,
          [type]: action.payload.state,
          [combinedType]: action.payload.state === 'combined' ? action.payload.value : '', // contains e.g. mapped_fixed, mapped_derived
          new_premium_logic: action.payload.new_premium_logic,
          endorsement_new_premium_logic: action.payload.endorsement_new_premium_logic
        }

        localStorageSave(action.payload.state, data, view)

        if (get(data, type) !== 'combined') {
          window.sessionStorage.setItem(`${view === 'endorsement' ? 'endorsement_premium_type' : 'new_premium_type'}`, JSON.stringify(get(data, type, '')))
        } else {
          window.sessionStorage.setItem(`${view === 'endorsement' ? 'endorsement_premium_type' : 'new_premium_type'}`, JSON.stringify(get(data, combinedType, '')))
        }

        return data
      }
      case 'update-key': {
        let data = {}
        const actionData = get(action, 'payload.data', {})
        const key = get(action, 'payload.key')

        data = setWith({ ...state }, key, actionData)
        return data
      }
      case 'update-store': {
        let data = {}
        const view = get(action, 'payload.view')
        const actionData = get(action, 'payload.data')
        const key = get(action, 'payload.key')
        const type = view === 'endorsement' ? 'endorsement_type' : 'type'

        data = setWith({ ...state }, key, actionData)

        if (get(data, type) !== 'combined') {
          localStorageSave(get(state, type), data, view)
        } else {
          localStorageSave(get(state, `${view === 'endorsement' ? 'endorsement_combined_type' : 'combined_type'}`), data, view)
        }
        return data
      }
      default:
        throw new Error()
    }
  }, initialState)

  return <Provider value={{ state, dispatch }}>{children}</Provider>
}

export { store, PremiumStateProvider }
