import { Row, Col, Form, Input, InputNumber, Button, Spin, Table } from 'antd'
import { get } from 'lodash'
import { existingPackageProduct } from '../../../../../../constants/WorkerType'

export default function CustomFieldPolicyNumberComponent (props) {
  const {
    getFieldDecorator,
    initialFormData,
    fieldCheckCondition,
    handleClearField,
    handleSearchExistingData,
    existingPackageProductData,
    buttonDisabledCheck,
    existingProductLoading,
    existingProductError,
    handleActiveNextButton
  } = props
  return (
    <Col span={24}>
      <Row type='flex'>
        <Col span={24}>
          <p className='custom-provider-heading'><b>Provider policy number format</b></p>
        </Col>
      </Row>
      <Row type='flex' justify='space-around'>
        <Col>
          <Form.Item extra='*case sensitive'>
            {
              getFieldDecorator('prefix_policy', {
                rules: [
                  {
                    required: fieldCheckCondition('policy_number_source', 'custom') && fieldCheckCondition('suffix_policy', ''),
                    message: 'required'
                  }
                ],
                initialValue: get(initialFormData, 'prefix_policy', '')
              })(<Input className='small-size' placeholder='prefix' onChange={handleClearField} />)
            }
          </Form.Item>
        </Col>
        <Col>
          <Form.Item>
            {
              getFieldDecorator('number_of_digits_policy', {
                rules: [
                  {
                    required: fieldCheckCondition('policy_number_source', 'custom'),
                    message: 'required'
                  },
                  {
                    pattern: /^([4-9]|1[012])$/,
                    message: 'possible value between 4 and 12 (inclusive)'
                  }
                  // { validator: formData.validator }
                ],
                initialValue: get(initialFormData, 'number_of_digits_policy')
              })(<InputNumber className='small-size' placeholder='no of digits' onChange={handleClearField} />)
            }
          </Form.Item>
        </Col>
        <Col>
          <Form.Item extra='*case sensitive'>
            {
              getFieldDecorator('suffix_policy', {
                rules: [
                  {
                    required: fieldCheckCondition('policy_number_source', 'custom') && fieldCheckCondition('prefix_policy', ''),
                    message: 'required'
                  }
                ],
                initialValue: get(initialFormData, 'suffix_policy', '')
              })(<Input className='small-size' placeholder='suffix' onChange={handleClearField} />)
            }
          </Form.Item>
        </Col>
        <Col>
          <Button
            type='primary'
            onClick={handleSearchExistingData}
            disabled={buttonDisabledCheck()}
          >
            Search
          </Button>
        </Col>
      </Row>
      <Row type='flex' justify='center'>
        <Col span={18}>
          <Spin spinning={existingProductLoading && !existingProductError}>
            <Table
              bordered
              columns={existingPackageProduct}
              dataSource={existingPackageProductData}
            />
          </Spin>
        </Col>
      </Row>
      <Row type='flex' justify='center'>
        <Col>
          <Form.Item label='Counter Key'>
            {
              getFieldDecorator('counter_key_policy', {
                rules: [
                  {
                    required: true,
                    message: 'required'
                  }
                ],
                initialValue: get(initialFormData, 'counter_key_policy', '')
              })(<Input className='small-size' placeholder='counter-key' onChange={handleActiveNextButton} />)
            }
          </Form.Item>
        </Col>
      </Row>
    </Col>
  )
}
