import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Form, Row, Col, Radio, notification, TreeSelect, Checkbox, InputNumber } from 'antd'
import { size, get } from 'lodash'
import WorkerWrapper from './index.style'
import Step3Actions from '../../../../../../../../redux/productConfig/actions'
import { localStorageCheck } from '../../../../../../util/localstorageCheck'
import { workerType } from '../../../PackageSection/commanFunctions'
import EditorWrapperComponent from './editor'
import CustomFieldPolicyNumberComponent from './customFieldPolicyNumberComponent'
import { childNode } from '../../../../../../components/formItem'

const {
  resetProductConfigRedux,
  getExistingProductPackage
} = Step3Actions
class WorkerType extends Component {
  state = {
    showCustom: '',
    selectedValue: [],
    existingPackageProductData: [],
    initialFormData: {},
    html: '',
    step2Data: [],
    validationDataInput: ''
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      existingProductMessage,
      existingProductData
    } = nextProps

    if (existingProductMessage === 'success') {
      const { data } = existingProductData
      this.setState({
        existingPackageProductData: get(data, 'details', [])
      })
      this.props.resetProductConfigRedux(['existingProductMessage'])
    }

    if (existingProductMessage !== 'success' && existingProductMessage !== undefined) {
      notification.error({
        message: 'Error',
        description: 'Error in Loading..'
      })
      this.props.resetProductConfigRedux(['existingProductMessage'])
    }
  }

  componentDidMount () {
    const { initialFormData } = this.state
    const { initialData, step2Data } = this.props
    if (step2Data.length > 0) {
      this.setState({
        step2Data
      })
    }
    const data = initialData || {}
    if (size(data) > 0 && size(initialFormData) === 0) {
      const localData = workerType(data)
      Object.keys(localData).forEach(item => {
        if (item === 'policy_creation_certificate_html') {
          this.setState({
            html: localData[item]
          })
        }
      })
      this.setState({
        initialFormData: localData
      })
    }
  }

  componentDidUpdate (previousProps, prevState) {
    const { stepHandler, form } = previousProps
    if (stepHandler) {
      const { getFieldsValue } = form
      const formData = getFieldsValue()
      if (get(formData, 'document_generation_source') === 'provider' || get(formData, 'policy_number_source') === 'provider') {
        stepHandler({ provider: true })
      } else {
        stepHandler({ provider: false })
      }
    }
  }

  onHandleSearchExistingData =() => {
    const { getFieldsValue, setFieldsValue } = this.props.form
    const formData = getFieldsValue()
    setFieldsValue({
      counter_key_policy: null
    })
    this.setState({
      existingPackageProductData: []
    })
    const data = {
      prefix: formData.prefix_policy,
      number_of_digits: formData.number_of_digits_policy,
      suffix: formData.suffix_policy
    }
    this.props.getExistingProductPackage({ body: data })
  }

  handleSearchValidationData = (e) => {
    this.setState({ validationDataInput: e.target.value })
  }

  handleSearchValidationBtn = () => {
    this.props.getValidationUniqueIdentifierList({
      code: this.state.validationDataInput
    })
  }

  buttonDisabledCheck =() => {
    const { getFieldsValue } = this.props.form
    const formData = getFieldsValue()
    if (formData.number_of_digits_policy) {
      if (formData.prefix_policy !== '' || formData.suffix_policy !== '') {
        return false
      } else {
        return true
      }
    } else {
      return true
    }
  }

  handleChangesRadioSection =(e) => {
    const radioValue = e.target.value
    const { form } = this.props
    if (radioValue !== 'custom' && radioValue !== 'provider') {
      if (radioValue === 'application_number') {
        form.setFieldsValue({
          counter_key_policy: null,
          prefix_policy: '',
          number_of_digits_policy: null,
          suffix_policy: ''
        })
      }
      form.setFieldsValue({
        replace_provider_policy_number_source: null
      })
    }
  }

  onhandleClearField = () => {
    const { form } = this.props
    form.setFieldsValue({
      counter_key_policy: null
    })
    this.setState({
      existingPackageProductData: []
    })
    this.props.nextButtonDisabled()
  }

  onHandleActiveNextButton = () => {
    this.props.nextButtonDisabled('true')
  }

  handleSetHTMLhandler =(val) => {
    this.setState({
      html: val
    })
  }

  render () {
    const { getFieldDecorator, getFieldValue } = this.props.form
    const { existingPackageProductData, html, initialFormData, step2Data } = this.state
    const { existingProductLoading, existingProductError } = this.props
    const attributesData = step2Data.length > 0 ? step2Data : (JSON.parse(window.sessionStorage.getItem('Step2')) || [])
    return (
      <WorkerWrapper>
        <Row type='flex' className='worker__row-field'>
          <Col span={24}><p className='aditional-info'>How are we getting Policy Number ?</p></Col>
          <Col span={24}>
            <Form.Item>
              {getFieldDecorator('policy_number_source', {
                rules: [
                  {
                    required: true,
                    message: 'policyNumber source required'
                  }
                  // { validator: formData.validator }
                ],
                initialValue: get(initialFormData, 'policy_number_source')
              })(
                <Radio.Group onChange={this.handleChangesRadioSection}>
                  <div>
                    <Radio value='application_number'>Use application number (App No)</Radio>
                  </div>
                  <div>
                    <Radio value='custom'>Use customer running number</Radio>
                  </div>
                  <div className='radio-component'>
                    <Radio value='payload'>same as policy data </Radio>
                    <Form.Item className='payload__attribute_field'>
                      {
                        getFieldDecorator('policy_number_derived_from_product_attribute_id', {
                          rules: [{
                            required: this.props.fieldCheckCondition('policy_number_source', 'payload')
                          }],
                          initialValue: get(initialFormData, 'policy_number_derived_from_product_attribute_id', null)
                        })(
                          <TreeSelect
                            // disabled={disableField}
                            // className={className}
                            placeholder='Select Attribute...'
                            treeDefaultExpandAll
                          >
                            {
                              childNode(attributesData)
                            }
                          </TreeSelect>
                        )
                      }
                    </Form.Item>
                  </div>
                  <div>
                    <Radio value='provider'>From Provider's API</Radio>
                  </div>
                </Radio.Group>
              )}
            </Form.Item>
          </Col>
          {
            (getFieldValue('policy_number_source') === 'provider') &&
              <Col className='skip-checkbox' span={24}>
                <Form.Item>
                  {
                    getFieldDecorator('skip_policy_number_from_provider', {
                      valuePropName: 'checked',
                      rules: [
                        {
                          required: false
                        }
                      ],
                      initialValue: get(initialFormData, 'skip_policy_number_from_provider', false)
                    })(
                      <Checkbox>
                        Skip Policy Number From Provider
                      </Checkbox>
                    )
                  }
                </Form.Item>
                <Form.Item>
                  <p>Provider Hit Timeout</p>
                  {
                    getFieldDecorator('provider_hit_timeout', {
                      rules: [
                        {
                          required: false
                        }
                      ],
                      initialValue: get(initialFormData, 'provider_hit_timeout')
                    })(
                      <InputNumber />
                    )
                  }
                </Form.Item>
              </Col>
          }
          {
            ((getFieldValue('policy_number_source') === 'provider') && (getFieldValue('skip_policy_number_from_provider') === true)) &&
              <Col className='skip-checkbox-option' span={24}>
                <Row type='flex'>
                  <Col span={24}><p className='aditional-info'>How are we getting Policy Number ?</p></Col>
                  <Col span={24}>
                    <Form.Item>
                      {getFieldDecorator('replace_provider_policy_number_source', {
                        rules: [
                          {
                            required: true,
                            message: 'policyNumber source required'
                          }
                        // { validator: formData.validator }
                        ],
                        initialValue: get(initialFormData, 'replace_provider_policy_number_source')
                      })(
                        <Radio.Group onChange={this.handleChangesRadioSection}>
                          <div>
                            <Radio value='application_number'>Use application number (App No)</Radio>
                          </div>
                          <div>
                            <Radio value='custom'>Use customer running number</Radio>
                          </div>
                        </Radio.Group>
                      )}
                    </Form.Item>
                  </Col>
                </Row>
              </Col>
          }
          {
            ((getFieldValue('policy_number_source') === 'custom') || (getFieldValue('replace_provider_policy_number_source') === 'custom')) &&
              <Col span={24}>
                <CustomFieldPolicyNumberComponent
                  getFieldDecorator={getFieldDecorator}
                  initialFormData={initialFormData}
                  fieldCheckCondition={this.props.fieldCheckCondition}
                  handleClearField={this.onhandleClearField}
                  handleSearchExistingData={this.onHandleSearchExistingData}
                  existingPackageProductData={existingPackageProductData}
                  buttonDisabledCheck={this.buttonDisabledCheck}
                  existingProductLoading={existingProductLoading}
                  existingProductError={existingProductError}
                  handleActiveNextButton={this.onHandleActiveNextButton}
                />
              </Col>
          }
        </Row>
        <Row type='flex' className='worker__row-field'>
          <Col span={24}><p className='aditional-info'>How are we getting Policy Document ?</p></Col>
          <Col span={24}>
            <Form.Item>
              {getFieldDecorator('document_generation_source', {
                rules: [
                  {
                    required: true,
                    message: 'required'
                  }
                  // { validator: formData.validator }
                ],
                initialValue: get(initialFormData, 'document_generation_source')
              })(
                <Radio.Group onChange={this.handleChangesRadioSection}>
                  <div>
                    <Radio value='not_required'>No document needed</Radio>
                  </div>
                  <div>
                    <Radio value='pasarpolis'>Generated by Pasarpolis</Radio>
                  </div>
                  <div>
                    <Radio value='provider'>From Provider's API</Radio>
                  </div>
                </Radio.Group>
              )}
            </Form.Item>
          </Col>
          {
            (this.props.fieldCheckCondition('document_generation_source', 'pasarpolis') || get(localStorageCheck(window.sessionStorage.getItem('formData')), 'document_generation_source', 'not_required') === 'pasarpolis') &&
              <Col span={24}>
                <Form.Item>
                  {getFieldDecorator('policy_creation_certificate_html', {
                    rules: [
                      {
                        required: this.props.fieldCheckCondition('document_generation_source', 'pasarpolis'),
                        message: 'required'
                      }
                      // { validator: formData.validator }
                    ],
                    initialValue: get(initialFormData, 'policy_creation_certificate_html', html)
                  })(
                    <EditorWrapperComponent
                      displayName='Previewer'
                      html={html}
                      onChange={this.handleSetHTMLhandler}
                      props={this.props.history}
                      step2Data={attributesData}
                    />
                  )}
                </Form.Item>
              </Col>
          }
        </Row>
      </WorkerWrapper>
    )
  }
}
WorkerType.defaultProps = {
  existingProductLoading: false,
  existingProductError: false
}
WorkerType.propTypes = {
  existingProductLoading: PropTypes.bool,
  existingProductError: PropTypes.bool
}
export default connect(
  state => ({
    existingProductMessage: state.ProductConfigurable.getExistinProductPackageMessage,
    existingProductData: state.ProductConfigurable.getExistinProductPackageData,
    existingProductLoading: state.Loading.GET_EXISTING_PRODUCT_PACKAGE,
    existingProductError: state.Error.GET_EXISTING_PRODUCT_PACKAGE
  }), {
    resetProductConfigRedux,
    getExistingProductPackage
  }
)(WorkerType)
