import React, { useState, useEffect, useRef } from "react";
import { connect } from "react-redux";
import policyActions from "../../../../../../../../../redux/policy/actions";
import {
  Form,
  Input,
  Button,
  Table,
  Popconfirm,
  message,
  Row,
  Col,
  Pagination,
} from "antd";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import VariableModal from "./components/VariableModal";

const { TextArea } = Input;

// Draggable row component
const DraggableRow = ({ index, moveRow, className, style, ...restProps }) => {
  const ref = useRef();
  const [{ isOver, dropClassName }, drop] = useDrop({
    accept: "DraggableRow",
    collect: (monitor) => {
      const { index: dragIndex } = monitor.getItem() || {};
      if (dragIndex === index) {
        return {};
      }
      return {
        isOver: monitor.isOver(),
        dropClassName: dragIndex < index ? " drop-over-downward" : " drop-over-upward",
      };
    },
    drop: (item) => {
      moveRow(item.index, index);
    },
  });

  const [, drag] = useDrag({
    type: "DraggableRow",
    item: { index },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  drop(drag(ref));

  return (
    <tr
      ref={ref}
      className={`${className}${isOver ? dropClassName : ""}`}
      style={{ cursor: "move", ...style }}
      {...restProps}
    />
  );
};

const PremiumV2 = ({
  attributesData = [],
  initialData = {},
  form,
  step2Data,
  // redux props
  getFormulaAttribute,
  getFormulaAttributeData,
  getFormulaAttributeMessage,
  deleteFormulaAttribute,
  deleteFormulaAttributeMessage,
  updateFormulaAttribute,
  updateFormulaAttributeMessage,
  resetReduxState,
}) => {
  const { getFieldDecorator } = form;
  const [variables, setVariables] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [totalItems, setTotalItems] = useState(0);
  const [offsetState, setOffsetState] = useState(0);
  const [limitState, setLimitState] = useState(10);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingIndex, setEditingIndex] = useState(null);

  // Fetch whenever offset/limit state changes
  useEffect(() => {
    fetchFormulaAttributes(offsetState, limitState);
  }, [offsetState, limitState]);

  useEffect(() => {
    if (
      getFormulaAttributeMessage === "success" ||
      getFormulaAttributeMessage.toLowerCase().includes("success")
    ) {
      const list =
        (getFormulaAttributeData && getFormulaAttributeData.data) || [];
      const mapped = Array.isArray(list)
        ? list.map((item) => ({
            sequence: item.sequence,
            variable: item.variable,
            static_value: item.static_value,
            attribute: item.product_attribute_id,
            attribute_name: item.product_attribute_name,
            fallback_value: item.fallback_value || "",
            sub_formula: item.sub_formula || "",
            extra_data: item.extra_data || "",
            id: item.ID,
          }))
        : [];
      setVariables(mapped);
      const meta = getFormulaAttributeData?.metadata || {};
      const total = typeof meta.count === "number" ? meta.count : mapped.length;
      setTotalItems(Number(total));
    }
  }, [getFormulaAttributeData, getFormulaAttributeMessage]);

  useEffect(() => {
    if (
      deleteFormulaAttributeMessage === "success" ||
      deleteFormulaAttributeMessage.toLowerCase().includes("success")
    ) {
      message.success("Variable deleted successfully!");
      fetchFormulaAttributes(offsetState, limitState);
      resetReduxState(["deleteFormulaAttributeMessage"]);
    } else if (deleteFormulaAttributeMessage) {
      message.error(
        deleteFormulaAttributeMessage || "Failed to delete variable."
      );
      resetReduxState(["deleteFormulaAttributeMessage"]);
    }
  }, [deleteFormulaAttributeMessage]);

  useEffect(() => {
    if (
      updateFormulaAttributeMessage === "success" ||
      updateFormulaAttributeMessage?.toLowerCase().includes("success")
    ) {
      message.success("Sequence updated successfully!");
      fetchFormulaAttributes(offsetState, limitState);
      resetReduxState(["updateFormulaAttributeMessage"]);
    } else if (updateFormulaAttributeMessage) {
      message.error(
        updateFormulaAttributeMessage || "Failed to update sequence."
      );
      resetReduxState(["updateFormulaAttributeMessage"]);
    }
  }, [updateFormulaAttributeMessage]);

  const columns = [
    {
      title: "Sequence",
      dataIndex: "sequence",
      key: "sequence",
      render: (_, record) => record.sequence,
    },
    {
      title: "Variable",
      dataIndex: "variable",
      key: "variable",
      render: (_, record) => record.variable,
    },
    {
      title: "Attribute",
      dataIndex: "attribute_name",
      key: "attribute_name",
      render: (_, record) => record.attribute_name,
    },
    {
      title: "Static Value",
      dataIndex: "static_value",
      key: "static_value",
      render: (_, record) => record.static_value,
    },
    {
      title: "Sub Formula",
      dataIndex: "sub_formula",
      key: "sub_formula",
      render: (_, record) => record.sub_formula,
    },
    {
      title: "Actions",
      key: "actions",
      render: (_, record, index) => (
        <span style={{ display: "flex", gap: 4 }}>
          <Button
            type="primary"
            size="small"
            onClick={() => handleEdit(record.id)}
          >
            Edit
          </Button>
          <Popconfirm
            title="Are you sure to delete this variable?"
            onConfirm={() => handleDelete(record.id)}
            okText="Yes"
            cancelText="No"
          >
            <Button type="danger" size="small" danger>
              Delete
            </Button>
          </Popconfirm>
        </span>
      ),
    },
  ];

  const fetchFormulaAttributes = (offset = 0, limit = 10) => {
    const productCode = initialData.product_code;
    const packageCode = initialData.code;

    if (productCode && packageCode && getFormulaAttribute) {
      const payload = {
        productCode,
        packageCode,
        offset: Number(offset),
        limit: Number(limit),
      };
      getFormulaAttribute(payload);
    }
  };

  const handleAddVariable = () => {
    setEditingIndex(null);
    setModalVisible(true);
  };

  const handleEdit = (index) => {
    setEditingIndex(index);
    setModalVisible(true);
  };

  const handleDelete = (index) => {
    deleteFormulaAttribute({
      id: index,
    });
  };

  const handleModalOk = () => {
    setModalVisible(false);
    setEditingIndex(null);
    fetchFormulaAttributes();
  };

  const handleModalCancel = () => {
    setModalVisible(false);
    setEditingIndex(null);
  };

  const moveRow = (dragIndex, hoverIndex) => {
    if (dragIndex === hoverIndex) {
      return;
    }

    const dragRow = variables[dragIndex];
    const hoverRow = variables[hoverIndex];

    if (!dragRow || !hoverRow) {
      return;
    }

    if (updateFormulaAttribute) {
      const payload = {
        productCode: initialData.product_code,
        packageCode: initialData.code,
        body: [{
          sequence: hoverRow.sequence,
          id: dragRow.id,
          variable: dragRow.variable,
          product_attribute_id: dragRow.attribute,
          static_value: dragRow.static_value,
          sub_formula: dragRow.sub_formula,
          extra_data: dragRow.extra_data ?? null,
        },{
          sequence: dragRow.sequence,
          id: hoverRow.id,
          variable: hoverRow.variable,
          product_attribute_id: hoverRow.attribute,
          static_value: hoverRow.static_value,
          sub_formula: hoverRow.sub_formula,
          extra_data: hoverRow.extra_data ?? null,
        }]
      }
      updateFormulaAttribute(payload);
    }
  };

  const components = {
    body: {
      row: DraggableRow,
    },
  };

  const onRow = (record, index) => ({
    index,
    moveRow,
  });

  const paginatedVariables = variables;

  return (
    <DndProvider backend={HTML5Backend}>
      <div
        style={{ padding: "20px", border: "1px solid #ddd", borderRadius: "8px" }}
      >
        <Row gutter={[16, 16]}>
          <Col span={24}>
            <label>FORMULA</label>
            <Form.Item>
              {getFieldDecorator("formula", {
                initialValue:
                  initialData?.formula || initialData?.formula_expression || "",
                rules: [
                  {
                    validator: (_, value, callback) => {
                      const useFormula = form.getFieldValue("use_formula");
                      const numericUseFormula = Number(
                        useFormula !== undefined && useFormula !== null
                          ? useFormula
                          : 0
                      );

                      if (numericUseFormula !== 1) {
                        callback();
                        return;
                      }

                      if (!value || !String(value).trim()) {
                        callback("Formula is required");
                        return;
                      }

                      callback();
                    },
                  },
                ],
              })(
                <TextArea
                  rows={4}
                  placeholder="Enter formula (e.g., X >= 1000 ? (A * B) + (C / D) : 200)"
                />
              )}
            </Form.Item>
          </Col>

          <Col span={24}>
            <Button type="primary" onClick={handleAddVariable}>
              Add Variable
            </Button>
          </Col>

          <Col span={24}>
            <Table
              dataSource={paginatedVariables}
              columns={columns}
              pagination={false}
              rowKey={(record) => record.id}
              bordered
              components={components}
              onRow={onRow}
            />
          </Col>

          <Col span={24} style={{ textAlign: "right" }}>
            <Pagination
              current={currentPage}
              pageSize={pageSize}
              total={totalItems}
              onChange={(page, size) => {
                setCurrentPage(page);
                setPageSize(size);
                setOffsetState((page - 1) * size);
                setLimitState(size);
              }}
              onShowSizeChange={(page, size) => {
                setCurrentPage(1);
                setPageSize(size);
                setOffsetState(0);
                setLimitState(size);
              }}
              showSizeChanger
              pageSizeOptions={["5", "10", "20", "50"]}
            />
          </Col>
        </Row>

        <VariableModal
          visible={modalVisible}
          onCancel={handleModalCancel}
          onOk={handleModalOk}
          editId={editingIndex}
          initialValues={editingIndex !== null ? variables?.find(v => v.id === editingIndex) : {}}
          attributesData={attributesData}
          step2Data={step2Data}
          initialData={initialData}
        />

        <style jsx>{`
          :global(.drop-over-upward) {
            border-top: 2px dashed #1890ff;
          }
          :global(.drop-over-downward) {
            border-bottom: 2px dashed #1890ff;
          }
        `}</style>
      </div>
    </DndProvider>
  );
};

export default connect(
  (state) => ({
    getFormulaAttributeData: state.Policy?.getFormulaAttributeData,
    getFormulaAttributeMessage: state.Policy?.getFormulaAttributeMessage,
    deleteFormulaAttributeData: state.Policy?.deleteFormulaAttributeData,
    deleteFormulaAttributeMessage: state.Policy?.deleteFormulaAttributeMessage,
    updateFormulaAttributeMessage: state.Policy?.updateFormulaAttributeMessage,
  }),
  {
    getFormulaAttribute: policyActions.getFormulaAttribute,
    deleteFormulaAttribute: policyActions.deleteFormulaAttribute,
    updateFormulaAttribute: policyActions.updateFormulaAttribute,
    resetReduxState: policyActions.resetReduxState,
  }
)(PremiumV2);
