import React, { useState } from 'react'
import { Tabs, Input } from 'antd'
import Premium from '../Premium'
import PremiumV2 from '../PremiumV2'

const { TabPane } = Tabs

export default function PremiumWrapper (props) {
  const { sectionView, form, fieldCheckCondition, initialData, step2Data } = props

  const { getFieldDecorator } = form

  const [tabNo, setTabNo] = useState(initialData.use_formula ? '2' : '1')

  const handleTabsChange = (tab) => {
    setTabNo(tab)

    form.setFieldsValue({
      use_formula: tab === '2' ? 1 : 0
    })

    const currentFormula = form.getFieldValue('formula')
    if (tab !== '2') {
      // Clear formula errors when switching to V1
      form.setFields({
        formula: {
          value: currentFormula,
          errors: []
        }
      })
    } else {
      // Re-validate formula after use_formula is committed so the validator sees the correct value
      setTimeout(() => {
        form.validateFields(['formula'], { force: true })
      }, 0)
    }
  }

  return (
    <>
      {getFieldDecorator('use_formula', {
        initialValue: initialData.use_formula ? 1 : 0
      })(<Input type='hidden' />)}

      <Tabs type='card' onChange={handleTabsChange} activeKey={tabNo}>

        <TabPane tab='Premium V1' key='1'>
          <Premium
            sectionView={sectionView}
            form={form}
            fieldCheckCondition={fieldCheckCondition}
            initialData={initialData}
            step2Data={step2Data}
          />
        </TabPane>

        <TabPane tab='Premium V2' key='2'>
          <PremiumV2
            sectionView={sectionView}
            form={form}
            fieldCheckCondition={fieldCheckCondition}
            initialData={initialData}
            step2Data={step2Data}
          />
        </TabPane>

      </Tabs>
    </>
  )
}
