import React, { useState, useEffect, Suspense } from 'react'
import { Row, Col, Form, Radio, Spin, Input, TreeSelect } from 'antd'
import { getFormItems, childNode } from './getFormItems'
import { get, size } from 'lodash'
import { coveragePeriod } from '../../../PackageSection/commanFunctions'

const CoveragePeriodStyleWrapper = React.lazy(() => import('./index.style'))

export default function CoveragePeriod ({ initialData, step2Data, sectionView, form, fieldCheckCondition }) {
  const [initialFormData, setInitialFormData] = useState({})
  const [step2DataState, setStep2DataState] = useState([])
  const { getFieldDecorator, getFieldValue } = form

  useEffect(() => {
    setStep2DataState(step2Data)
    if (size(initialData) > 0) {
      setInitialFormData(coveragePeriod(initialData))
    } else {
      setInitialFormData(initialData)
    }
  }, [step2Data, initialData])

  const checkEndorsement = (sectionView === 'endorsement')

  const handleStartDateChange = (e) => {
    const { setFieldsValue } = form
    const radioValue = e.target.value
    if (radioValue === 'true') {
      setFieldsValue({
        [`${checkEndorsement ? 'endorsement_coverage_start_buffer_days' : 'coverage_start_buffer_days'}`]: '',
        [`${checkEndorsement ? 'endorsement_coverage_start_derived_from_product_attribute_id' : 'coverage_start_derived_from_product_attribute_id'}`]: null
      })
    }
  }

  const handleEndDateChange = (e) => {
    const { setFieldsValue } = form
    const radioValue = e.target.value
    switch (radioValue) {
      case 1:
        setFieldsValue({
          [`${checkEndorsement ? 'endorsement_coverage_end_derived_from_product_attribute_id' : 'coverage_end_derived_from_product_attribute_id'}`]: null,
          [`${checkEndorsement ? 'endorsement_coverage_end_diff_months_from_coverage_start' : 'coverage_end_diff_months_from_coverage_start'}`]: ''
        })
        break
      case 2:
        setFieldsValue({
          [`${checkEndorsement ? 'endorsement_coverage_end_derived_from_product_attribute_id' : 'coverage_end_derived_from_product_attribute_id'}`]: null,
          [`${checkEndorsement ? 'endorsement_coverage_end_diff_days_from_coverage_start' : 'coverage_end_diff_days_from_coverage_start'}`]: ''
        })
        break
      case 3:
        setFieldsValue({
          [`${checkEndorsement ? 'endorsement_coverage_end_diff_days_from_coverage_start' : 'coverage_end_diff_days_from_coverage_start'}`]: '',
          [`${checkEndorsement ? 'endorsement_coverage_end_diff_months_from_coverage_start' : 'coverage_end_diff_months_from_coverage_start'}`]: ''
        })
        break
      default: return ''
    }
  }

  const handleStartTimeChange = (e) => {
    const { setFieldsValue } = form
    const radioValue = e.target.value
    if (radioValue) {
      setFieldsValue({
        [`${checkEndorsement ? 'endorsement_static_coverage_start_time_part' : 'static_coverage_start_time_part'}`]: null
      })
    }
  }

  const handleEndTimeChange = (e) => {
    const { setFieldsValue } = form
    const radioValue = e.target.value
    if (radioValue) {
      setFieldsValue({
        [`${checkEndorsement ? 'endorsement_static_coverage_end_time_part' : 'static_coverage_end_time_part'}`]: null
      })
    }
  }

  const attributesData = step2DataState.length > 0 ? step2DataState : (JSON.parse(window.sessionStorage.getItem('Step2')) || [])

  const handleDerivedDate = () => {
    if (!(getFieldValue('coverage_end_derived_from_product_attribute_id') || getFieldValue('endorsement_coverage_end_derived_from_product_attribute_id'))) return null

    const attributeId = getFieldValue('coverage_end_derived_from_product_attribute_id')

    const selectedAttr = attributesData?.find(attr => attr.id === attributeId)

    if (selectedAttr?.datatype === 'date') {
      return (
        <>
          <p className='radio__component_text-content'>Duration Derived Unit</p>
          {
            getFormItems.call(this, {
              form,
              formName: `${checkEndorsement ? 'endorsement_coverage_end_diff_derived_unit' : 'coverage_end_diff_derived_unit'}`,
              type: 'choices',
              required: false,
              options: [
                { id: 'hour', code: 'hour' },
                { id: 'day', code: 'day' },
                { id: 'week', code: 'week' },
                { id: 'month', code: 'month' },
                { id: 'year', code: 'year' }
              ],
              optionKey: 'id',
              optionDisplayName: 'code',
              className: 'drop-down-menu',
              message: 'Waiting Period Unit is required',
              initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_diff_derived_unit' : 'coverage_end_diff_derived_unit'}`, null)
            })
          }
        </>
      )
    } else {
      return null
    }
  }

  return (
    <Suspense fallback={<Spin tip='CoverPeriod Loading ...' />}>
      <CoveragePeriodStyleWrapper>
        <Row type='flex' className='coverage__row-field'>
          <Col span={24}><p className='aditional-info'>Start Date time</p></Col>
          <Col span={24}>
            <Form.Item>
              {
                getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_start_same_as_policy_endorsement' : 'coverage_start_same_as_policy_creation'}`, {
                  rules: [
                    {
                      required: true,
                      message: 'Start date time required'
                    }
                  ],
                  initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_start_same_as_policy_endorsement' : 'coverage_start_same_as_policy_creation'}`, 'true')
                })(
                  <Radio.Group onChange={handleStartDateChange}>
                    <div>
                      <Radio value='true'> Same as policy creation date time </Radio>
                    </div>
                    <div className='radio_component'>
                      <Radio value='false' />
                      <div className='radio-wrapper'>
                        <p>Days from &nbsp;</p>
                        <Form.Item>
                          {
                            getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_start_derived_from_product_attribute_id' : 'coverage_start_derived_from_product_attribute_id'}`, {
                              rules: [{
                                required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_coverage_start_same_as_policy_endorsement' : 'coverage_start_same_as_policy_creation'}`, 'false')
                              }],
                              initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_start_derived_from_product_attribute_id' : 'coverage_start_derived_from_product_attribute_id'}`, null)
                            })(
                              <TreeSelect
                                className='attribute-select'
                                // disabled={disableField}
                                placeholder='Select attributes'
                                treeDefaultExpandAll
                              >
                                {
                                  childNode(attributesData)
                                }
                              </TreeSelect>
                            )
                          }
                        </Form.Item>
                      </div>
                    </div>
                  </Radio.Group>
                )
              }
            </Form.Item>
          </Col>

          <Col span={24} className='edit-field'>
            <Form.Item>
              {
                getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_start_time_part_modified' : 'start_time_part_modified'}`, {
                  rules: [
                    {
                      required: true,
                      message: 'Start time required'
                    }
                  ],
                  initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_start_time_part_modified' : 'start_time_part_modified'}`, true)
                })(
                  <Radio.Group onChange={handleStartTimeChange}>
                    <div>
                      <Radio value> Always starts from 00:00:00 </Radio>
                    </div>
                    <div className='radio_component'>
                      <Radio value={false} />
                      <div className='radio-wrapper'>
                        <p className='radio__component_text-content'>Coverage Start Time</p>
                        <Form.Item>
                          {
                            getFieldDecorator(`${checkEndorsement ? 'endorsement_static_coverage_start_time_part' : 'static_coverage_start_time_part'}`, {
                              rules: [{
                                required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_static_coverage_start_time_part' : 'static_coverage_start_time_part'}`, 'false')
                              }],
                              initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_static_coverage_start_time_part' : 'static_coverage_start_time_part'}`, null)
                            })(
                              <Input type='time' step='1' />
                            )
                          }
                        </Form.Item>
                      </div>
                    </div>
                  </Radio.Group>
                )
              }
            </Form.Item>

          </Col>

          <Col span={24} className='add__field'>
            <Form.Item label='Add Start date buffer in days'>
              {
                getFormItems.call(this, {
                  form,
                  formName: `${checkEndorsement ? 'endorsement_coverage_start_buffer_days' : 'coverage_start_buffer_days'}`,
                  type: 'numeric',
                  required: false,
                  className: 'small-size inlineBlock',
                  message: 'required',
                  initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_start_buffer_days' : 'coverage_start_buffer_days'}`, 0) || 0
                })
              }
            </Form.Item>
          </Col>
        </Row>

        <Row type='flex' className='coverage__row-field'>
          <Col span={24}><p className='aditional-info'>End Date time</p></Col>
          <Col span={24}>
            <Form.Item>
              {getFieldDecorator(`${checkEndorsement ? 'endorsement_end_date_time_type' : 'end_date_time_type'}`, {
                rules: [
                  {
                    required: true,
                    message: 'End date time required'
                  }
                ],
                initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_end_date_time_type' : 'end_date_time_type'}`)
              })(
                <Radio.Group onChange={handleEndDateChange}>
                  <div className='radio_component'>
                    <Radio value={1} />
                    <div className='radio-wrapper'>
                      <Form.Item>
                        {
                          getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_end_diff_days_from_coverage_start' : 'coverage_end_diff_days_from_coverage_start'}`, {
                            rules: [{
                              required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_end_date_time_type' : 'end_date_time_type'}`, 1),
                              message: 'End date time required'
                            }],
                            initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_diff_days_from_coverage_start' : 'coverage_end_diff_days_from_coverage_start'}`, '')
                          })(<Input />)
                        }
                      </Form.Item>
                      <p className='radio__component_text-content'>days since start date (example: 1 January 2020 - 30 April 2020)</p>
                    </div>
                  </div>
                  <div className='radio_component'>
                    <Radio value={2} />
                    <div className='radio-wrapper'>
                      <Form.Item>
                        {
                          getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_end_diff_months_from_coverage_start' : 'coverage_end_diff_months_from_coverage_start'}`, {
                            rules: [{
                              required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_end_date_time_type' : 'end_date_time_type'}`, 2)
                            }],
                            initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_diff_months_from_coverage_start' : 'coverage_end_diff_months_from_coverage_start'}`, null)
                          })(<Input />)
                        }
                      </Form.Item>
                      <p className='radio__component_text-content'>months since start date (date to date)</p>
                    </div>
                  </div>
                  <div className='radio_component'>
                    <Radio value={3} />
                    <div className='radio-wrapper'>
                      <p className='radio__component_text-content'>from</p>
                      <Form.Item>
                        {
                          getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_end_derived_from_product_attribute_id' : 'coverage_end_derived_from_product_attribute_id'}`, {
                            rules: [{
                              required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_end_date_time_type' : 'end_date_time_type'}`, 3)
                            }],
                            initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_derived_from_product_attribute_id' : 'coverage_end_derived_from_product_attribute_id'}`, null)
                          })(
                            <TreeSelect
                              className='attribute-select'
                              // disabled={disableField}
                              placeholder='Select attributes'
                              treeDefaultExpandAll
                            >
                              {
                                childNode(attributesData)
                              }
                            </TreeSelect>
                          )
                        }
                      </Form.Item>

                      {
                        (getFieldValue('coverage_end_derived_from_product_attribute_id') || getFieldValue('endorsement_coverage_end_derived_from_product_attribute_id')) && handleDerivedDate()
                      }
                    </div>
                  </div>
                </Radio.Group>
              )}
            </Form.Item>
          </Col>

          <Col span={24} className='edit-field'>
            <Form.Item>
              {
                getFieldDecorator(`${checkEndorsement ? 'endorsement_coverage_end_time_part_modified' : 'end_time_part_modified'}`, {
                  rules: [
                    {
                      required: true,
                      message: 'End time required'
                    }
                  ],
                  initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_time_part_modified' : 'end_time_part_modified'}`, true)
                })(
                  <Radio.Group onChange={handleEndTimeChange}>
                    <div>
                      <Radio value> Always ends on 23:59:59 </Radio>
                    </div>
                    <div className='radio_component'>
                      <Radio value={false} />
                      <div className='radio-wrapper'>
                        <p className='radio__component_text-content'>Coverage End Time</p>
                        <Form.Item>
                          {
                            getFieldDecorator(`${checkEndorsement ? 'endorsement_static_coverage_end_time_part' : 'static_coverage_end_time_part'}`, {
                              rules: [{
                                required: fieldCheckCondition(`${checkEndorsement ? 'endorsement_static_coverage_end_time_part' : 'static_coverage_end_time_part'}`, 'false')
                              }],
                              initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_static_coverage_end_time_part' : 'static_coverage_end_time_part'}`, null)
                            })(
                              <Input type='time' step='1' />
                            )
                          }
                        </Form.Item>
                      </div>
                    </div>
                  </Radio.Group>
                )
              }
            </Form.Item>

          </Col>

          <Col span={24} className='add__field'>
            <Form.Item label='Add end date buffer in days'>
              {
                getFormItems.call(this, {
                  form,
                  formName: `${checkEndorsement ? 'endorsement_coverage_end_buffer_days' : 'coverage_end_buffer_days'}`,
                  type: 'numeric',
                  required: false,
                  className: 'small-size inlineBlock',
                  message: 'required',
                  initialValue: get(initialFormData, `${checkEndorsement ? 'endorsement_coverage_end_buffer_days' : 'coverage_end_buffer_days'}`, 0)
                })
              }
            </Form.Item>
          </Col>
          <Col span={24} className='edit-field'>
            {
              getFormItems.call(this, {
                form,
                formName: `${checkEndorsement ? 'has_endorsement_waiting_period' : 'has_waiting_period'}`,
                type: 'checkbox',
                require: false,
                className: 'small-size',
                label: `${checkEndorsement ? 'Endorsement Waiting Period' : 'Waiting Period'}`,
                initialValue: get(initialFormData, `${checkEndorsement ? 'has_endorsement_waiting_period' : 'has_waiting_period'}`)
              })
            }
          </Col>

          {
            checkEndorsement
              ? form.getFieldValue('has_endorsement_waiting_period') &&
                <div className='endorsement-sub-section'>
                  <Col span={24}>
                    <p className='form-label'>Endorsement Waiting Period Derived Product Attribute Id</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'endorsement_waiting_period_derived_product_attribute_id',
                        type: 'nested-tree-select',
                        required: fieldCheckCondition('has_endorsement_waiting_period', 'true'),
                        options: attributesData,
                        optionKey: 'id',
                        optionDisplayName: 'name',
                        className: 'small-size',
                        initialValue: get(initialFormData, 'endorsement_waiting_period_derived_product_attribute_id')
                      })
                    }
                    </div>
                  </Col>
                  <Col span={24}>
                    <p className='form-label'>Endorsement Waiting Period</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'endorsement_waiting_period',
                        type: 'numeric',
                        required: fieldCheckCondition('has_waiting_period', 'true'),
                        className: 'small-size',
                        initialValue: get(initialFormData, 'endorsement_waiting_period')
                      })
                    }
                    </div>
                  </Col>
                  <Col span={24}>
                    <p className='form-label'>Endorsement Waiting Period Unit</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'endorsement_waiting_period_unit',
                        type: 'choices',
                        required: fieldCheckCondition('has_endorsement_waiting_period', 'true'),
                        options: [
                          { id: 'hour', code: 'hour' },
                          { id: 'day', code: 'day' },
                          { id: 'week', code: 'week' },
                          { id: 'month', code: 'month' }
                        ],
                        optionKey: 'id',
                        optionDisplayName: 'code',
                        className: 'small-size',
                        message: 'Waiting Period Unit is required',
                        initialValue: get(initialFormData, 'endorsement_waiting_period_unit')
                      })
                    }
                    </div>
                  </Col>

                  <Col span={24} className='checkBoxDiv'>
                    {
                    getFormItems.call(this, {
                      form,
                      formName: 'add_waiting_period_in_endorsement_coverage_start_date',
                      type: 'checkbox',
                      require: fieldCheckCondition('has_endorsement_waiting_period', 'true'),
                      className: 'small-size',
                      label: 'Add Waiting Period in Endorsement Coverage Start Date',
                      initialValue: get(initialFormData, 'add_waiting_period_in_endorsement_coverage_start_date')
                    })
                  }
                  </Col>
                </div>
              : form.getFieldValue('has_waiting_period') &&
                <div className='endorsement-sub-section'>
                  <Col span={24}>
                    <p className='form-label'>Waiting Period Derived Product Attribute Id</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'waiting_period_derived_product_attribute_id',
                        type: 'nested-tree-select',
                        required: fieldCheckCondition('has_waiting_period', 'true'),
                        options: attributesData,
                        optionKey: 'id',
                        optionDisplayName: 'name',
                        className: 'small-size',
                        initialValue: get(initialFormData, 'waiting_period_derived_product_attribute_id', null)
                      })
                    }
                    </div>
                  </Col>
                  <Col span={24}>
                    <p className='form-label'>Waiting Period</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'waiting_period',
                        type: 'numeric',
                        required: fieldCheckCondition('has_waiting_period', 'true'),
                        className: 'small-size',
                        initialValue: get(initialFormData, 'waiting_period', null)
                      })
                    }
                    </div>
                  </Col>
                  <Col span={24}>
                    <p className='form-label'>Waiting Period Unit</p>
                    <div className='extra-info-div'>
                      {
                      getFormItems.call(this, {
                        form,
                        formName: 'waiting_period_unit',
                        type: 'choices',
                        required: fieldCheckCondition('has_waiting_period', 'true'),
                        options: [
                          { id: 'hour', code: 'hour' },
                          { id: 'day', code: 'day' },
                          { id: 'week', code: 'week' },
                          { id: 'month', code: 'month' }
                        ],
                        optionKey: 'id',
                        optionDisplayName: 'code',
                        className: 'small-size',
                        message: 'Waiting Period Unit is required',
                        initialValue: get(initialFormData, 'waiting_period_unit')
                      })
                    }
                    </div>
                  </Col>

                  <Col span={24} className='checkBoxDiv'>
                    {
                    getFormItems.call(this, {
                      form,
                      formName: 'add_waiting_period_in_coverage_start_date',
                      type: 'checkbox',
                      require: fieldCheckCondition('has_waiting_period', 'true'),
                      className: 'small-size',
                      label: 'Add Waiting Period in Coverage Start Date',
                      initialValue: get(initialFormData, 'add_waiting_period_in_coverage_start_date')
                    })
                  }
                  </Col>

                </div>
          }

        </Row>
      </CoveragePeriodStyleWrapper>
    </Suspense>
  )
}
