/* eslint-disable react-hooks/exhaustive-deps */
import React, { lazy, Suspense, useState, useEffect, useContext } from 'react'
import { Row, Col, Form, Select, Spin } from 'antd'
import { get, size } from 'lodash'
import { store } from './store'

const PremiumTypeComponent = lazy(() => import('./premiumType'))
const PremiumStyleWrapper = lazy(() => import('./index.style'))

const { Option } = Select
const Premium = ({ sectionView, initialData, step2Data, form }) => {
  const { dispatch } = useContext(store)
  const [premiumTypeState, setPremiumTypeState] = useState('fixed')
  const [step2DataState, setStep2Data] = useState([])
  const [initialFormData, setInitialFormData] = useState({})

  const premiumTypeView = sectionView === 'endorsement' ? 'endorsement_premium_type' : 'premium_type'
  const premiumTypeLogic = sectionView === 'endorsement' ? 'endorsement_new_premium_logic' : 'new_premium_logic'

  useEffect(() => {
    return () => {
      window.sessionStorage.removeItem(premiumTypeLogic)
      window.sessionStorage.removeItem(premiumTypeView)
    }
  }, [])
  useEffect(() => {
    if (step2Data.length > 0) {
      setStep2Data(step2Data)
    }
  }, [step2Data])

  useEffect(() => {
    const data = initialData || {}
    if (size(data) > 0 && size(initialFormData) === 0) {
      const type = get(data, premiumTypeView) ? get(data, premiumTypeView).split('_') : ''
      if (type.length > 1) {
        // TODO: Remove
        setPremiumTypeState('combined')
        setInitialFormData(data)
        dispatch({
          type: 'init-state',
          payload: {
            state: 'combined',
            value: get(data, premiumTypeView),
            view: sectionView,
            new_premium_logic: data.new_premium_logic,
            endorsement_new_premium_logic: data.endorsement_new_premium_logic
          }
        })
      } else {
        const premiumView = get(data, premiumTypeView)
        if (premiumView) {
          setPremiumTypeState(get(data, premiumTypeView))
          setInitialFormData(data)
          dispatch({
            type: 'init-state',
            payload: {
              state: get(data, premiumTypeView, ''),
              value: '',
              view: sectionView,
              new_premium_logic: data.new_premium_logic,
              endorsement_new_premium_logic: data.endorsement_new_premium_logic
            }
          })
        } else {
          setPremiumTypeState('fixed')
          setInitialFormData(data)
          dispatch({
            type: 'init-state',
            payload: {
              state: 'fixed',
              value: 'fixed',
              view: sectionView,
              new_premium_logic: data.new_premium_logic,
              endorsement_new_premium_logic: data.endorsement_new_premium_logic
            }
          })
        }
      }
    } else {
      dispatch({
        type: 'init-state',
        payload: {
          state: 'fixed',
          value: 'fixed',
          view: sectionView,
          new_premium_logic: initialFormData.new_premium_logic,
          endorsement_new_premium_logic: initialFormData.endorsement_new_premium_logic
        }
      })
    }
  }, [initialData])

  const { getFieldDecorator } = form
  const attributesData = step2DataState.length > 0 ? step2DataState : (JSON.parse(window.sessionStorage.getItem('Step2')) || [])

  const premiumType = [
    { code: 'fixed', name: 'Fixed' },
    { code: 'derived', name: 'Derived' },
    { code: 'mapped', name: 'Map Based' },
    { code: 'ranged', name: 'Range Based' },
    { code: 'age', name: 'Duration Based' },
    { code: 'combined', name: 'Combined Premium' },
    { code: 'nested', name: 'Nested' },
    { code: 'multiplied', name: 'Multiplied' },
    { code: 'summation', name: 'Summation' },
    { code: 'hook', name: 'Pre-defined Function' },
  ]

  const handlePremiumChangeHandler = (e) => {
    // setResetState(true)
    dispatch({
      type: 'reset-all',
      payload: {
        view: sectionView
      }
    })
    setPremiumTypeState(e)
    setInitialFormData({})
    dispatch({
      type: 'update-type',
      payload: {
        state: e,
        value: e,
        view: sectionView
      }
    })
  }

  // const fieldCheckHandler = (key, value) => {
  //   this.props.fieldCheckCondition(key, value)
  // }

  return (
    <Suspense fallback={<Spin tip='Loading Premium ....' />}>
      <PremiumStyleWrapper>
        <Row type='flex' justify='center'>
          <Col span={22}>
            <p className='aditional-info'>Premium calculation</p>
          </Col>
          <Col span={22}>
            <Form.Item>
              {
                getFieldDecorator(`${sectionView === 'endorsement' ? 'endorsement_premium_type' : 'premium_type'}`, {
                  rules: [
                    {
                      required: true,
                      message: 'required'
                    }
                  ],
                  initialValue: premiumTypeState || get(initialFormData, `${sectionView === 'endorsement' ? 'endorsement_premium_type' : 'premium_type'}`)
                })(
                  <Select onChange={handlePremiumChangeHandler}>
                    {
                      premiumType.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)
                    }
                  </Select>
                )
              }
            </Form.Item>
          </Col>
          <Col span={22}>
            <PremiumTypeComponent
              sectionView={sectionView}
              type={premiumTypeState}
              initialFormData={initialFormData}
              attributesData={attributesData}
              getFieldDecorator={getFieldDecorator}
            />
          </Col>
        </Row>
      </PremiumStyleWrapper>
    </Suspense>
  )
}

export default Premium
