import React, { Suspense, useState } from 'react'
import { Spin, Form, Input, Icon } from 'antd'
import UpdataQueueNameWrapper from './style'
import { get } from 'lodash'

const DevelopersOnly = ({ form, fieldCheckCondition, initialData }) => {
  const { getFieldDecorator } = form
  const [queueWorkerState, setQueueWorkerState] = useState(false)
  const [concurrencyWorkerState, setConcurrencyWorkerState] = useState(false)
  const [queueInputDisabled, setQueueNameDisabled] = useState(true)
  const [concurrencyInputDisabled, setConcurrencyInputDisabled] = useState(true)

  const getFormContent = (label, key, defaultValue, type, disableCond) => {
    return (
      <div className='form-content'>
        <label>{label}</label>
        <Form.Item>
          {getFieldDecorator(key, {
            rules: [
              {
                required: false
              }
            ],
            initialValue: get(
              initialData,
              key,
              defaultValue
            )
          })(<Input type={type} disabled={disableCond} />)}
        </Form.Item>
      </div>
    )
  }

  const queueNameCol = [
    {
      label: 'Creation Worker Queue Name',
      key: 'creation_worker_queue_name',
      defaultValue: 'creation-default',
      type: 'string'
    },
    {
      label: 'Endorsement Worker Queue Name',
      key: 'endorsement_worker_queue_name',
      defaultValue: 'endorsement-default',
      type: 'string'
    },
    {
      label: 'Cancellation Worker Queue Name',
      key: 'cancellation_worker_queue_name',
      defaultValue: 'cancellation-default',
      type: 'string'
    },
    {
      label: 'Termination Worker Queue Name',
      key: 'termination_worker_queue_name',
      defaultValue: 'termination-default',
      type: 'string'
    },
    {
      label: 'Renewal Worker Queue Name',
      key: 'renewal_worker_queue_name',
      defaultValue: 'renewal-default',
      type: 'string'
    },
    {
      label: 'CallBack Worker Queue Name',
      key: 'callback_worker_queue_name',
      defaultValue: 'callback-default',
      type: 'string'
    }
  ]

  const concurrencyCol = [
    {
      label: 'Creation Worker Concurrency',
      key: 'creation_worker_concurrency',
      defaultValue: 5,
      type: 'number'
    },
    {
      label: 'Endorsement Worker Concurrency',
      key: 'endorsement_worker_concurrency',
      defaultValue: 1,
      type: 'number'
    },
    {
      label: 'Cancellation Worker Concurrency',
      key: 'cancellation_worker_concurrency',
      defaultValue: 1,
      type: 'number'
    },
    {
      label: 'Termination Worker Concurrency',
      key: 'termination_worker_concurrency',
      defaultValue: 1,
      type: 'number'
    },
    {
      label: 'Renewal Worker Concurrency',
      key: 'renewal_worker_concurrency',
      defaultValue: 1,
      type: 'number'
    },
    {
      label: 'CallBack Worker Concurrency',
      key: 'callback_worker_concurrency',
      defaultValue: 1,
      type: 'number'
    }
  ]

  const genralCol = [
    {
      label: 'Document SVC Queue Number',
      key: 'document_svc_queue_number',
      defaultValue: 'document_svc_queue_number',
      type: 'string'
    }
  ]

  return (
    <Suspense fallback={<Spin tip='DevelopersOnlyTab Loading ...' />}>
      <UpdataQueueNameWrapper>
        <div className='QueueWrapper'>
          Queue Name <Icon type={`${queueWorkerState ? 'up-square' : 'down-square'}`} onClick={() => setQueueWorkerState(!queueWorkerState)} value={queueWorkerState} />
          {queueWorkerState && <Icon type='edit' className='floatR' onClick={() => setQueueNameDisabled(!queueInputDisabled)} />}
          {queueWorkerState &&
            <div className='form-body'>
              {queueNameCol?.map((col) =>
                <React.Fragment key={col.key}>
                  {getFormContent(col.label, col.key, col.defaultValue, col.type, queueInputDisabled)}
                </React.Fragment>
              )}
            </div>}
        </div>

        <div className='ConCurrencyWrapper'>
          Worker Concurrency <Icon type={`${concurrencyWorkerState ? 'up-square' : 'down-square'}`} onClick={() => setConcurrencyWorkerState(!concurrencyWorkerState)} value={concurrencyWorkerState} />
          {concurrencyWorkerState && <Icon type='edit' className='floatR' onClick={() => setConcurrencyInputDisabled(!concurrencyInputDisabled)} />}
          {concurrencyWorkerState &&
            <div className='form-body'>
              {concurrencyCol?.map((col) =>
                <React.Fragment key={col.key}>
                  {getFormContent(col.label, col.key, col.defaultValue, col.type, concurrencyInputDisabled)}
                </React.Fragment>
              )}
            </div>}
        </div>
        <div>
          <div className='form-body'>
            {genralCol?.map((col) =>
              <React.Fragment key={col.key}>
                {getFormContent(col.label, col.key, col.defaultValue, col.type)}
              </React.Fragment>
            )}
          </div>
        </div>
      </UpdataQueueNameWrapper>
    </Suspense>
  )
}

export default DevelopersOnly
