import React from 'react'
import { Input, Form, DatePicker, Radio, Select, InputNumber, Checkbox, TreeSelect } from 'antd'
const { TreeNode } = TreeSelect

export function getFormItems (formData) {
  const {
    form,
    placeHolder = ' ',
    disableField = false,
    type, label = ' ',
    initialValue = '',
    required = false,
    className = ' ',
    extra = '',
    loading = false,
    message = '',
    help = ''
  } = formData
  const { getFieldDecorator } = form

  switch (type) {
    case 'numeric':
      return (
        <Form.Item>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: message
                }
                // { validator: formData.validator }
              ],
              initialValue: initialValue
            })(<InputNumber className={className} disabled={disableField} placeholder={placeHolder} />)
          }
        </Form.Item>
      )
    case 'string':
    case 'alphanumeric':
      return (
        <Form.Item extra={extra} help={help}>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: message
                }
                // { validator: formData.validator }
              ],
              initialValue: initialValue
            })(<Input className={className} disabled={disableField} placeholder={placeHolder} />)
          }
        </Form.Item>
      )
    case 'textarea':
      return (
        <Form.Item>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: ''
                }
                // { validator: formData.validator }
              ],
              initialValue: initialValue
            })(<Input.TextArea
              rows={formData.row || 4}
              className={className}
              placeholder={''}
            />)
          }
        </Form.Item>
      )
    case 'dob':
      return (
        <Form.Item>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                {
                  required: required,
                  message: ''
                }
                // { validator: formData.validator }
              ],
              initialValue: initialValue
            })(
              <DatePicker
                className={className}
                format={'YYYY-MM-DD'}
                placeholder={''}
                // disable selection above today
              />
            )
          }
        </Form.Item>
      )
    case 'email':
      return (
        <Form.Item>
          {
            getFieldDecorator(formData.formName, {
              rules: [
                { required: true, message: '' },
                { type: 'email', message: '' }
              ],
              initialValue: initialValue
            })(
              <Input className={className} disabled={!!initialValue} placeholder={''} />
            )
          }
        </Form.Item>
      )
    case 'radio':
      return (
        <Form.Item>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: ''
              }
              // { validator: formData.validator }
            ],
            initialValue: initialValue
          })(
            <Radio.Group>
              {
                formData.options.map((option, index) => {
                  return (
                    <Radio key={index} value={option[formData.optionKey]}>
                      {
                        typeof option[formData.optionDisplayName] === 'function' ? option[formData.optionDisplayName]() : option[formData.optionDisplayName]
                      }
                    </Radio>
                  )
                })
              }
            </Radio.Group>
          )}
        </Form.Item>
      )
    case 'choices':
      return (
        <Form.Item>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: ''
              }
              // { validator: formData.validator }
            ],
            initialValue: initialValue
          })(
            <Select
              // disabled={disableField}
              className={className}
              showSearch
              placeholder={''}
              filterOption={(input, option) =>
                option.props.children
                  .toLowerCase()
                  .indexOf(input.toLowerCase()) >= 0
              }
              disabled={disableField}
              loading={loading}
            >
              {
                formData.options.map((option, index) => {
                  return (
                    <Select.Option key={index} value={option[formData.optionKey]}>
                      {option[formData.optionDisplayName]}
                    </Select.Option>
                  )
                })
              }
            </Select>)
          }
        </Form.Item>
      )
    case 'checkbox':
      return (
        <Form.Item>
          {getFieldDecorator(formData.formName, {
            valuePropName: 'checked',
            rules: [
              {
                required: required,
                message: ''
              }
              // { validator: formData.validator }
            ],
            initialValue: initialValue !== '' ? initialValue : false
          })(<Checkbox className={className}>{label}</Checkbox>)
          }
        </Form.Item>
      )
    case 'nested-tree-select':
      return (
        <Form.Item>
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: ''
              }
              // { validator: formData.validator }
            ],
            initialValue: initialValue
          })(
            <TreeSelect
              // disabled={disableField}
              className={className}
              placeholder={''}
              treeDefaultExpandAll
              disabled={disableField}
              loading={loading}
            >
              {
                childNode(formData.options)
              }
            </TreeSelect>)
          }
        </Form.Item>
      )
    default:
      return null
  }
}

export function childNode (data = []) {
  if (Array.isArray(data)) {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span className='main-text'>{item.name}</span> <br />
            {item.attribute_type && <span className='sub-text'>({item.attribute_type})</span>}
          </div>
        )
        return (
          <TreeNode value={item.id} title={data} />
        )
      } else {
        return (
          <TreeNode title={item.name}>
            {childNode(item.nested)}
          </TreeNode>
        )
      }
    })
  }
}
