/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import { Row, Col, Select, Icon, TreeSelect } from 'antd'
import { childNode } from '../../../../../../../components/formItem'
import BlackListStyleWrapper from './blackListComponent.style'
import { get } from 'lodash'

const { Option } = Select

export default function BlackListConfigComponent (props) {
  const {
    configArray,
    hashListHandler,
    productAttributeHandler,
    additionFunction,
    deletionFunction,
    productAttributes,
    hashItemsList,
    defaultHashlist
  } = props
  const [configList, setConfigList] = useState([])
  const [attributes, setAttributes] = useState([])
  const [hashItems, setHashItems] = useState([])

  useEffect(() => {
    if (productAttributes.length > 0 && attributes.length === 0) {
      setAttributes(productAttributes)
    }
    if (hashItemsList.length > 0 && hashItems.length === 0) {
      setHashItems(hashItemsList)
    }

    setConfigList(configArray)
  }, [productAttributes, hashItemsList, configArray])

  return configList.map((item, index) => {
    const attributesDefaultValue = attributes.find(e => e.id === item.attributeId)
    return (
      <BlackListStyleWrapper key={index}>
        <React.Fragment className='width100'>
          <Row type='flex' gutter={20}>
            <Col>
              <TreeSelect
                // disabled={disableField}
                value={get(attributesDefaultValue, 'name', '')}
                onChange={(value) => productAttributeHandler(value, item.id)}
                className='validation-field'
                placeholder='Select data to blackList'
                treeDefaultExpandAll
              >
                {
                  childNode(attributes)
                }
              </TreeSelect>
            </Col>
            <Col>
              {
                hashItems.length > 0 &&
                  <Select
                    showSearch
                    defaultValue={defaultHashlist}
                    value={item.hashId}
                    className='validation-field'
                    onChange={(value) => hashListHandler(value, item.id)}
                    placeholder='Select hash method (optional)'
                    filterOption={(input, option) =>
                      option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                  >
                    {
                    hashItems.map(item2 => (<Option className='option-overflow' key={item2.id} value={item2.id}>{item2.name}</Option>))
                  }
                  </Select>
              }
            </Col>
            <Col span={4} className='action-buttons'>
              <div className='icon-div'>
                {
                  item.addButtonVisible &&
                    <Icon
                      className='dynamic-add-button button-size'
                      type='plus-circle'
                      theme='filled'
                      onClick={additionFunction}
                    />
                }
                {
                  item.deleteButtonVisible &&
                    <Icon
                      style={{ marginLeft: 5 }}
                      className='dynamic-delete-button button-size'
                      type='minus-circle'
                      theme='filled'
                      onClick={() => deletionFunction(item.id)}
                    />
                }
              </div>
            </Col>
          </Row>
        </React.Fragment>
      </BlackListStyleWrapper>
    )
  })
}
