export const localStorageSave = (type, state = {}, premiumType) => {
  // CALLED ON SUBMIT
  const premiumTypeValue = premiumType === 'endorsement' ? 'endorsement_new_premium_logic' : 'new_premium_logic'

  let data = {}
  switch (type) {
    case 'fixed':
    case 'multiplied':
    case 'summation':
    case 'derived':
    case 'age':
    case 'ranged':
    case 'mapped':
    case 'nested':
    case 'combined':
    case 'hook':
    case 'ranged_derived':
    case 'ranged_mapped':
    case 'mapped_derived':
    case 'age_mapped':
    case 'age_derived':
    case 'endorsement_fixed':
    case 'endorsement_derived':
    case 'endorsement_age':
    case 'endorsement_ranged':
    case 'endorsement_mapped':
    case 'endorsement_mapped_derived':
    case 'endorsement_age_derived':
    case 'endorsement_ranged_derived':
    case 'endorsement_age_mapped':
    case 'endorsement_ranged_mapped':
      // data = get(state, type, {})
      if (premiumType === 'endorsement') {
        data = state.endorsement_new_premium_logic
      } else {
        data = state.new_premium_logic
      }
      break
    default: return null
  }
  window.sessionStorage.setItem(premiumTypeValue, JSON.stringify(data))
}
