import React from 'react'
import PropTypes from 'prop-types'
import { Collapse, Icon, notification } from 'antd'
import { connect } from 'react-redux'
import CollapseStyleWrapper from './index.style'
import collapseData from './collapseData'
import _, { hasIn, size } from 'lodash'
import { PremiumStateProvider } from './Premium/store'

class PackageComponent extends React.Component {
  state = {
    step1Data: {},
    step2Data: [],
    permissionsBasedCol: []
  }

  componentDidMount () {
    const { permissions } = this.props
    let columns = collapseData.call(this)

    columns = _.remove(columns, function (col) {
      // If col does not have any kind permission
      if (!col.permission) {
        return col
      } else {
        // col has permission and user has that permission
        if (permissions.includes(col.permission)) {
          return col
        }
      }
    })

    this.setState({ permissionsBasedCol: columns })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      step1Data,
      step2Data
    } = nextProps
    if (size(step2Data) > 0) {
      this.setState({
        step2Data
      })
    }
    if (size(step1Data) > 0) {
      this.setState({
        step1Data
      })
    } else {
      notification.warning({
        message: "Can't create Package",
        description:
          'Product creation data not found. Go Back to detail Page or product creation page.'
      })
    }
  }

  checkRequiredCondition =(code, value) => {
    const { form } = this.props
    const formBody = form.getFieldsValue()
    if (hasIn(formBody, code)) {
      return formBody[code] === value
    }
  }

  changePanel = (e) => {
    this.props.onChangePanel(e)
  }

  disabledNextButton = (data) => {
    this.props.nextButtonEnabledFunction(data)
  }

  render () {
    const {
      currentPanelState,
      packageData,
      editForm,
      history,
      stepHandler
    } = this.props
    const { step1Data, step2Data, permissionsBasedCol } = this.state
    return (
      <PremiumStateProvider>
        <CollapseStyleWrapper>
          {
            size(step1Data) > 0 &&
              <Collapse
                // defaultActiveKey={currentPanelState}
                activeKey={currentPanelState}
                expandIconPosition='right'
                onChange={(e) => this.changePanel(e)}
                expandIcon={({ isActive }) => <Icon type='down-square' rotate={isActive ? 180 : 0} style={{ fontSize: 25 }} />}
              >
                {
                  permissionsBasedCol?.map((item, index) => {
                    return (
                      <Collapse.Panel header={item.header} key={Number(item.id)}>
                        {item.render(packageData, editForm, step1Data, history, step2Data, stepHandler)}
                      </Collapse.Panel>
                    )
                  })
                }
              </Collapse>
          }
        </CollapseStyleWrapper>
      </PremiumStateProvider>
    )
  }
}
PackageComponent.defaultProps = {
  currentPanelState: [1],
  pacakageData: {}
}
PackageComponent.propTypes = {
  currentPanelState: PropTypes.array,
  onChangePannel: PropTypes.func,
  pacakageData: PropTypes.object
}

export default connect(
  state => ({
    permissions: state.Auth.permissions
  }),
  {}
)(PackageComponent)
