import React, { useEffect, useRef } from "react";
import { Modal, Form, Input, Select, notification } from "antd";
import { connect } from "react-redux";
import policyActions from "../../../../../../../../../../../redux/policy/actions";
// Using antd notification for success/error messages

const { TextArea } = Input;
const { Option } = Select;
const FormItem = Form.Item;

const VariableModal = ({
  visible,
  onCancel,
  onOk,
  initialValues,
  attributesData,
  form,
  editId,
  step2Data,
  initialData,
  createFormulaAttribute,
  updateFormulaAttribute,
  updateFormulaAttributeMessage,
  createFormulaAttributeMessage,
  resetReduxState,
}) => {
  const { getFieldDecorator } = form;
  const isEdit = !!editId;

  const prevVisibleRef = useRef(false);

  useEffect(() => {
    if (visible && !prevVisibleRef.current) {
      form.resetFields();
      if (initialValues && Object.keys(initialValues).length > 0) {
        form.setFieldsValue(initialValues);
      }
    }
    prevVisibleRef.current = visible;
  }, [visible, initialValues, form]);

  useEffect(() => {
    if (createFormulaAttributeMessage || updateFormulaAttributeMessage) {
      if (
        createFormulaAttributeMessage === "Success" ||
        createFormulaAttributeMessage.includes("success") ||
        updateFormulaAttributeMessage === "Success" ||
        updateFormulaAttributeMessage.includes("success")
      ) {
        notification.success({
          message: "Success",
          description: `Formula attribute ${updateFormulaAttributeMessage ? "updated" : "created"} successfully!`,
        });
        form.resetFields();
        onOk();
      } else {
        notification.error({
          message: "Error",
          description: `Failed to ${updateFormulaAttributeMessage ? "update" : "create"} formula attribute`,
        });
      }
      // reset redux state after handling API response
      if (resetReduxState) {
        resetReduxState([
          "createFormulaAttributeMessage",
          "createFormulaAttributeData",
          "updateFormulaAttributeMessage",
          "updateFormulaAttributeData",
        ]);
      }
    }
  }, [createFormulaAttributeMessage, updateFormulaAttributeMessage]);

  const handleOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        if (initialData?.product_code && initialData?.code) {
          const payload = {
            productCode: initialData.product_code,
            packageCode: initialData.code,
            body: isEdit ? [{
              sequence: initialValues?.sequence,
              id: editId,
              variable: values.variable,
              product_attribute_id: values.attribute,
              static_value: +values.static_value,
              sub_formula: values.sub_formula,
              extra_data: values.extra_data ?? null,
            }] : {
              variable: values.variable,
              product_attribute_id: values.attribute,
              static_value: +values.static_value,
              sub_formula: values.sub_formula,
              extra_data: values.extra_data ?? null,
            },
          };

          if (isEdit) {
            updateFormulaAttribute(payload);
            return;
          }
          createFormulaAttribute(payload);
        }
      }
    });
  };

  // Prefer using step2Data as the attributes source when it is an array
  const attributes = Array.isArray(step2Data)
    ? step2Data
    : attributesData || [];

  return (
    <Modal
      title="Variable Configuration"
      visible={visible}
      onOk={handleOk}
      onCancel={onCancel}
      okText="Submit"
      cancelText="Cancel"
      width={600}
    >
      <Form layout="vertical">
        <FormItem label="Variable">
          {getFieldDecorator("variable", {
            rules: [{ required: true, message: "Please enter variable name" }],
          })(<Input placeholder="e.g., A, B, X" />)}
        </FormItem>

        <FormItem label="Attribute">
          {getFieldDecorator("attribute")(
            <Select placeholder="Select Attribute">
              {attributes && attributes.length > 0 ? (
                attributes.map((attr) => (
                  <Option key={attr.id} value={attr.id}>
                    {attr.name || attr.code}
                  </Option>
                ))
              ) : (
                <Option value="default">Default Attribute</Option>
              )}
            </Select>
          )}
        </FormItem>

        <FormItem label="Static Value">
          {getFieldDecorator("static_value")(
            <Input placeholder="e.g., 100, true, 'text'" />
          )}
        </FormItem>

        <FormItem label="Sub Formula">
          {getFieldDecorator("sub_formula")(
            <TextArea rows={3} placeholder="e.g., (A + B) * C" />
          )}
        </FormItem>

        <FormItem label="Extra Data">
          {getFieldDecorator("extra_data")(
            <TextArea rows={3} placeholder="JSON or additional metadata" />
          )}
        </FormItem>
      </Form>
    </Modal>
  );
};

export default connect(
  (state) => ({
    createFormulaAttributeMessage: state.Policy?.createFormulaAttributeMessage,
    createFormulaAttributeData: state.Policy?.createFormulaAttributeData,
    updateFormulaAttributeMessage: state.Policy?.updateFormulaAttributeMessage,
    updateFormulaAttributeData: state.Policy?.updateFormulaAttributeData,
  }),
  {
    createFormulaAttribute: policyActions.createFormulaAttribute,
    updateFormulaAttribute: policyActions.updateFormulaAttribute,
    resetReduxState: policyActions.resetReduxState,
  }
)(Form.create()(VariableModal));
