import React, { Component } from 'react'
import { Row, Col, Form } from 'antd'
import { get, size } from 'lodash'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import BasicInfoActions from '../../../../../../../../redux/productConfig/actions'
import { getFormItems } from '../../../../../../components/formItem'
import BasicInfoStyleWrapper from './index.style'
import { localStorageCheck } from '../../../../../../util/localstorageCheck'
import { basicInfoMapper } from '../../../PackageSection/commanFunctions'
const {
  editProduct,
  getProductRegulatoryCategories,
  getProductCategories,
  getAllProductProviders,
  getAllProductTimezones,
  getAllProductCountries,
  resetProductConfigRedux,
  productDetailsAttributes
} = BasicInfoActions

class BasicInfo extends Component {
  constructor (props) {
    super(props)
    this.state = {
      initialFormData: {},
      regulatoryCategory: localStorageCheck(window.sessionStorage.getItem('regulatoryCategory')) || [],
      category_Id: localStorageCheck(window.sessionStorage.getItem('Step1')) || [],
      providerData: localStorageCheck(window.sessionStorage.getItem('provider')) || [],
      timezoneData: localStorageCheck(window.sessionStorage.getItem('timezone')) || [],
      countriesData: localStorageCheck(window.sessionStorage.getItem('countriesData')) || []
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      categoryList,
      categoriesMessage,
      regulatoryCategoryList,
      regulatoryCategoriesMessage,
      getAllProvidersData,
      getAllProvidersDataMessage,
      getAllTimeZoneData,
      getAllTimeZoneDataMessage,
      getAllCountriesData,
      getAllCountriesDataMessage,
      productDetailAttributes,
      productDetailAttributesMessage
    } = nextProps

    if (categoriesMessage === 'success') {
      const category = get(categoryList, 'data.details', [])
      this.setState({
        category: category
      })
      window.sessionStorage.setItem('category', JSON.stringify(category))
      this.props.resetProductConfigRedux(['getProductCategoriesMessage'])
    }
    if (regulatoryCategoriesMessage === 'success') {
      const regulatoryCategory = get(regulatoryCategoryList, 'data.details', [])
      this.setState({
        regulatoryCategory: regulatoryCategory
      })
      window.sessionStorage.setItem('regulatoryCategory', JSON.stringify(regulatoryCategory))
      this.props.resetProductConfigRedux(['getProductRegulatoryCategoriesMessage'])
    }
    if (getAllProvidersDataMessage === 'success') {
      const providerData = get(getAllProvidersData, 'data.details', [])
      this.setState({
        providerData: providerData
      })
      window.sessionStorage.setItem('provider', JSON.stringify(providerData))
      this.props.resetProductConfigRedux(['getAllProvidersDataMessage'])
    }
    if (getAllTimeZoneDataMessage === 'success') {
      this.setState({
        timezoneData: get(getAllTimeZoneData, 'data.details', [])
      })
      window.sessionStorage.setItem('timezone', JSON.stringify(get(getAllTimeZoneData, 'data.details', [])))
      this.props.resetProductConfigRedux(['getAllTimeZoneDataMessage'])
    }
    if (getAllCountriesDataMessage === 'success') {
      this.setState({
        countriesData: get(getAllCountriesData, 'data.details', [])
      })
      window.sessionStorage.setItem('countriesData', JSON.stringify(get(getAllCountriesData, 'data.details', [])))
      this.props.resetProductConfigRedux(['getAllCountriesDataMessage'])
    }
    if (productDetailAttributesMessage === 'success') {
      window.sessionStorage.setItem('Step2', JSON.stringify(get(productDetailAttributes, 'data.details', [])))
      this.props.resetProductConfigRedux(['productDetailAttributesMessage'])
    }
  }

  async componentDidMount () {
    this.props.getProductCategories()
    this.props.getProductRegulatoryCategories()
    const { initialData } = this.props
    const { initialFormData } = this.state
    const localProviderdata = localStorageCheck(window.sessionStorage.getItem('provider')) || []
    const countriesData = localStorageCheck(window.sessionStorage.getItem('countriesData')) || []
    const timezoneData = localStorageCheck(window.sessionStorage.getItem('timezone')) || []
    const productAttributes = localStorageCheck(window.sessionStorage.getItem('Step2')) || []

    if (productAttributes.length === 0) {
      const productCode = get(this.props.step1Data, 'code', '')
      await this.props.productDetailsAttributes({ query: { productCode: productCode, type: 'creation,endorsement' } })
    }
    if (localProviderdata.length === 0) {
      await this.props.getAllProductProviders()
    }
    if (timezoneData.length === 0) {
      await this.props.getAllProductTimezones()
    }
    if (countriesData.length === 0) {
      await this.props.getAllProductCountries()
    }

    const data = initialData || {}
    if (size(data) > 0 && size(initialFormData) === 0) {
      const localData = basicInfoMapper(data)

      this.setState({
        initialFormData: localData
      })
    }
  }

  // onSubmitHandler = e => {
  //   e.preventDefault()
  //   const { form } = this.props
  //   this.props.form.validateFields((err, values) => {
  //     if (!err) {
  //       const formBody = form.getFieldsValue()
  //       const data = {
  //         ...formBody,
  //         'cancellation_flow_type': formBody['cancellation_flow_type'] ? formBody['cancellation_flow_type'] : '',
  //         'termination_flow_type': formBody['termination_flow_type'] ? formBody['termination_flow_type'] : ''
  //       }
  //       window.sessionStorage.setItem('basicInfo', JSON.stringify(data))
  //       this.props.changePanel(2)
  //     }
  //   })
  // }
  render () {
    const {
      editForm, categoryListLoading, categoriesError,
      regulatoryCategoryListLoading, regulatoryCategoriesError
    } = this.props
    const {
      providerData, regulatoryCategory, category, timezoneData,
      countriesData, initialFormData
    } = this.state

    const { getFieldValue } = this.props.form
    const terminationFlow = [
      {
        code: 'with_refund',
        name: 'Termination with refund flow'
      },
      {
        code: 'without_refund',
        name: 'Termination without refund flow'
      }
    ]
    const cancellationFlow = [
      {
        code: 'with_refund',
        name: 'Cancelation with refund flow'
      },
      {
        code: 'without_refund',
        name: 'Cancelation without refund flow'
      }
    ]
    return (
      <BasicInfoStyleWrapper>
        {/* <Form onSubmit={this.onSubmitHandler}> */}
        <Row type='flex' justify='center'>
          <Col span={18}><p className='form-label'>Package code</p></Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'code',
                type: 'alphanumeric',
                required: true,
                className: 'small-size',
                message: 'Package Code is required',
                disableField: editForm,
                initialValue: get(initialFormData, 'code')
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}><p className='form-label'>Package name</p></Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'name',
                type: 'alphanumeric',
                required: true,
                className: 'small-size',
                message: 'Package Name is required',
                initialValue: get(initialFormData, 'name')
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}>
            <p className='form-label'>Category</p>
          </Col>
          <Col span={18}>
            {
                getFormItems.call(this, {
                  formName: 'category_id',
                  type: 'choices',
                  required: true,
                  options: category || [],
                  optionKey: 'id',
                  loading: categoryListLoading && !categoriesError,
                  optionDisplayName: 'name',
                  className: 'small-size',
                  initialValue: get(initialFormData, 'category_id')
                })
              }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}>
            <p className='form-label'>Regulatory</p>
          </Col>
          <Col span={18}>
            {
                getFormItems.call(this, {
                  formName: 'regulatory_category_id',
                  type: 'choices',
                  required: true,
                  options: regulatoryCategory || [],
                  optionKey: 'id',
                  loading: regulatoryCategoryListLoading && !regulatoryCategoriesError,
                  optionDisplayName: 'name',
                  className: 'small-size',
                  initialValue: get(initialFormData, 'regulatory_category_id')
                })
              }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}><p className='form-label'>Insurance Provider</p></Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'provider_code',
                type: 'choices',
                required: true,
                options: providerData || [],
                optionKey: 'code',
                optionDisplayName: 'name',
                className: 'small-size',
                message: 'Insurance Provider is required',
                initialValue: get(initialFormData, 'provider_code')
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}><p className='form-label'>Timezone</p></Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'timezone_id',
                type: 'choices',
                required: true,
                options: timezoneData || [],
                optionKey: 'id',
                optionDisplayName: 'code',
                className: 'small-size',
                message: 'TimeZone is required',
                initialValue: get(initialFormData, 'timezone_id')
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}><p className='form-label'>Countries</p></Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'country_id',
                type: 'choices',
                required: true,
                options: countriesData || [],
                optionKey: 'id',
                optionDisplayName: 'code',
                className: 'small-size',
                message: 'countries is required',
                initialValue: get(initialFormData, 'country_id')
              })
            }
          </Col>
          <Col span={18}>
            {
              getFormItems.call(this, {
                formName: 'edit_policy_flag',
                type: 'checkbox',
                require: false,
                className: 'small-size',
                label: 'Policy editable in Control Panel',
                initialValue: get(initialFormData, 'edit_policy_flag', true)
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={18}><p className='aditional-info'>Additional flow options:</p></Col>
          <Col span={18}>
            <>
              {
                getFormItems.call(this, {
                  formName: 'has_termination_flow',
                  type: 'checkbox',
                  require: false,
                  className: 'small-size',
                  label: 'Termination flow',
                  initialValue: get(initialFormData, 'has_termination_flow')
                })
              }
              {
                getFieldValue('has_termination_flow') &&
                  <Row type='flex'>

                    <Col span={18}>
                      {
                        getFormItems.call(this, {
                          formName: 'termination_flow_type',
                          type: 'radio',
                          required: true,
                          options: terminationFlow || [],
                          optionKey: 'code',
                          optionDisplayName: 'name',
                          className: 'small-size',
                          initialValue: get(initialFormData, 'termination_flow_type')
                        })
                      }
                    </Col>
                    <Col span={24} className='add__field'>
                      <Form.Item label='Add termination buffer in days'>
                        {
                getFormItems.call(this, {
                  formName: 'termination_buffer_days',
                  type: 'numeric',
                  required: false,
                  className: 'small-size inlineBlock',
                  message: 'required',
                  initialValue: get(initialFormData, 'termination_buffer_days', 0) || 0
                })
              }
                      </Form.Item>
                    </Col>
                  </Row>
              }
            </>
          </Col>
          <Col span={18}>
            <>
              {
                getFormItems.call(this, {
                  formName: 'has_cancellation_flow',
                  type: 'checkbox',
                  require: false,
                  className: 'small-size',
                  label: 'Cancelation flow',
                  initialValue: get(initialFormData, 'has_cancellation_flow', false)
                })
              }
              {
                getFieldValue('has_cancellation_flow') &&
                  <Row type='flex'>
                    <Col span={18}>
                      {
                        getFormItems.call(this, {
                          formName: 'cancellation_flow_type',
                          type: 'radio',
                          required: true,
                          options: cancellationFlow || [],
                          optionKey: 'code',
                          optionDisplayName: 'name',
                          className: 'small-size',
                          initialValue: get(initialFormData, 'cancellation_flow_type')
                        })
                      }
                    </Col>
                    <Col span={24} className='add__field'>
                      <Form.Item label='Add cancellation buffer in days'>
                        {
                getFormItems.call(this, {
                  formName: 'cancellation_buffer_days',
                  type: 'numeric',
                  required: false,
                  className: 'small-size inlineBlock',
                  message: 'required',
                  initialValue: get(initialFormData, 'cancellation_buffer_days', 0) || 0
                })
              }
                      </Form.Item>
                    </Col>
                  </Row>
              }
            </>
          </Col>
        </Row>
      </BasicInfoStyleWrapper>
    )
  }
}
BasicInfo.propTypes = {
  regulatoryCategoriesError: PropTypes.bool,
  regulatoryCategoryList: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.string
  }),
  regulatoryCategoryListLoading: PropTypes.bool,
  categoriesError: PropTypes.bool,
  categoryList: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.string
  }),
  categoryListLoading: PropTypes.bool,
  getAllTimeZoneData: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.bool
  }),
  getAllProvidersData: PropTypes.arrayOf(PropTypes.object),
  getAllCountriesData: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.bool
  })
}
BasicInfo.defaultProps = {
  regulatoryCategoriesError: false,
  regulatoryCategoryList: {
    data: {
      details: []
    },
    message: '',
    success: true
  },
  regulatoryCategoryListLoading: false,
  categoriesError: false,
  categoryList: {
    data: {
      details: []
    },
    message: '',
    success: true
  },
  categoryListLoading: false,
  getAllProvidersData: [],
  getAllTimeZoneData: {
    data: {
      details: []
    },
    message: '',
    success: false
  },
  getAllCountriesData: {
    data: {
      details: []
    },
    message: '',
    success: false
  }
}

export default connect(
  state => ({
    regulatoryCategoryList: state.ProductConfigurable.getProductRegulatoryCategories,
    regulatoryCategoryListLoading: state.Loading.GET_PRODUCT_REGULATORY_CATEGORIES,
    regulatoryCategoriesError: state.Error.GET_PRODUCT_REGULATORY_CATEGORIES,
    regulatoryCategoriesMessage: state.ProductConfigurable.getProductRegulatoryCategoriesMessage,
    categoryList: state.ProductConfigurable.getProductCategories,
    categoryListLoading: state.Loading.GET_PRODUCT_CATEGORIES,
    categoriesError: state.Error.GET_PRODUCT_CATEGORIES,
    categoriesMessage: state.ProductConfigurable.getProductCategoriesMessage,
    getAllProvidersData: state.ProductConfigurable.getAllProviders,
    getAllProvidersDataMessage: state.ProductConfigurable.getAllProvidersMessage,
    getAllTimeZoneData: state.ProductConfigurable.getAllTimezones,
    getAllTimeZoneDataMessage: state.ProductConfigurable.getAllTimezonesMessage,
    getAllCountriesData: state.ProductConfigurable.getAllCountries,
    getAllCountriesDataMessage: state.ProductConfigurable.getAllCountriesMessage,
    productDetailAttributes: state.ProductConfigurable.productDetailAttributes,
    productDetailAttributesMessage: state.ProductConfigurable.productDetailAttributesMessage

  }), {
    editProduct,
    getProductRegulatoryCategories,
    getProductCategories,
    getAllProductProviders,
    getAllProductTimezones,
    getAllProductCountries,
    resetProductConfigRedux,
    productDetailsAttributes
  }
)(BasicInfo)
